// --- 1. 収録全薬剤のマスターデータベース (DRUG_DB) ---
const DRUG_DB = [
  { name: "ベシケア", gen: "ソリフェナシンコハク酸塩", cat: "08. 泌尿器（抗コリン薬 / OAB）", char: "M3受容体選択的遮断薬！1日1回の過活動膀胱標準治療薬", desc: "膀胱平滑筋M3受容体を高選択的に遮断。口渇・便秘あり。閉塞隅角緑内障・尿閉に絶対禁忌。QT延長リスクに注意。CYP3A4代謝。", gId: "c20", cSec: "sec-ren" },
  { name: "ステーブラ / ウリトス", gen: "イミダフェナシン", cat: "08. 泌尿器（抗コリン薬 / OAB）", char: "BBB通過しにくく中枢副作用が最小！高齢者に使いやすい抗コリン薬", desc: "M3/M1受容体遮断薬。P糖蛋白排出基質のため脳内移行が極めて低く、抗コリン薬の中でせん妄・認知機能低下リスクが最小。1日2回朝夕食後服用。", gId: "c20", cSec: "sec-ren" },
  { name: "トビアーゼ", gen: "フェソテロジンフマル酸塩", cat: "08. 泌尿器（抗コリン薬 / OAB）", char: "プロドラッグ設計の1日1回徐放錠！噛み砕き・粉砕不可", desc: "エステラーゼで速やかに活性代謝物5-HMTに変換。4mgから8mgへ増量可能。※徐放性構造のため噛み砕き・粉砕厳禁。閉塞隅角緑内障禁忌。", gId: "c20", cSec: "sec-ren" },
  { name: "ネオキシテープ", gen: "オキシブチニン", cat: "08. 泌尿器（経皮吸収型抗コリン薬 / OAB）", char: "日本唯一のOAB貼付剤！肝初回通過を回避し口渇が大幅激減", desc: "経皮吸収型オキシブチニン製剤。嚥下困難患者や胃瘻患者に最適。肝代謝回避により口渇原因代謝物が激減。貼付部位は毎日変更（かぶれ防止）。緑内障禁忌。", gId: "c20", cSec: "sec-ren" },
  { name: "バップフォー", gen: "プロピベリン塩酸塩", cat: "08. 泌尿器（抗コリン＋Ca拮抗 / OAB）", char: "抗コリン＋平滑筋直接作用のデュアル作用！神経因性膀胱にも適応", desc: "抗コリン作用と平滑筋直接作用（Ca拮抗作用）を併せ持つ。パーキンソン病や脳血管障害に伴う過活動膀胱・頻尿にも適応。口渇・便秘・緑内障禁忌。", gId: "c20", cSec: "sec-ren" },
  { name: "ペリアクチン", gen: "シプロヘプタジン塩酸塩", cat: "06. 精神神経（抗セロトニン薬 / 解毒）", char: "セロトニン症候群の救命特効薬！強力な5-HT2受容体遮断作用", desc: "第1世代抗ヒスタミン薬兼強力な抗セロトニン薬。セロトニン症候群発症時の第一選択解毒薬（初期12mg経口・胃管投与）。強い眠気、口渇、食欲亢進。緑内障・前立腺肥大禁忌。", gId: "c6", cSec: "sec-psy" },
  { name: "ダントリウム", gen: "ダントロレンナトリウム水和物", cat: "06. 精神神経（筋弛緩薬 / 悪性症候群特効薬）", char: "悪性症候群（NMS）の救命特効薬！筋小胞体Ca放出を直接遮断", desc: "筋小胞体リアノジン受容体を遮断し鉛管様筋固縮・超高熱を速やかに解除。悪性症候群・悪性高熱症の特効薬（静注用20〜40mg急速静注➔カプセル内服）。肝機能障害・脱力に注意。", gId: "c6", cSec: "sec-psy" },
  { name: "パーロデル", gen: "ブロモクリプチンメシル酸塩", cat: "06. 精神神経（ドパミンアゴニスト / NMS治療）", char: "悪性症候群（NMS）の中枢ドパミン枯渇を強力回復する治療薬", desc: "麦角系ドパミン受容体作動薬。悪性症候群における中枢D2受容体遮断・枯渇状態を回復させる治療薬としてダントロレンと併用される。乳汁漏出症・パーキンソン病適応。", gId: "c6", cSec: "sec-psy" },
  { name: "アジレクト", gen: "ラサギリンメシル酸塩", cat: "06. 精神神経（パーキンソン病MAO-B阻害）", char: "アンフェタミン代謝物なし！初期単剤からウェアリングオフまで1日1回", desc: "第2世代選択的非可逆的MAO-B阻害薬。中枢刺激・不眠が出にくい。抗うつ薬（SSRI/SNRI/三環系）、トラマドール、デキストロメトルファンとの【セロトニン症候群併用禁忌】厳守。", gId: "c30", cSec: "sec-psy" },
  { name: "ドパコール / ネオドパストン", gen: "レボドパ・カルビドパ水和物", cat: "06. 精神神経（パーキンソン病L-ドパ/DCI）", char: "パーキンソン病治療の絶対的ゴールドスタンダード！脳内ドパミンを直接補給", desc: "L-ドパ＋脱炭酸酵素阻害薬（カルビドパ）。運動症状の改善力最強。長期使用でウェアリングオフ・ジスキネジアが必発。急な中止による悪性症候群に厳重警戒。", gId: "c30", cSec: "sec-psy" },
  { name: "マドパー", gen: "レボドパ・ベンセラジド塩酸塩", cat: "06. 精神神経（パーキンソン病L-ドパ/DCI）", char: "ベンセラジド配合のL-ドパ製剤！ネオドパストンと同等の強力効果", desc: "L-ドパ配合錠。1回100〜200mg。脱炭酸酵素阻害薬ベンセラジドにより末梢分解を防ぎ脳内移行を向上。胃腸障害時は食後服用。", gId: "c30", cSec: "sec-psy" },
  { name: "シンメトレル", gen: "アマンタジン塩酸塩", cat: "06. 精神神経（ドパミン遊離促進/NMDA拮抗）", char: "L-ドパ誘発性ジスキネジア（不随意運動）の特効薬！", desc: "NMDA拮抗＋ドパミン遊離促進。元抗ウイルス薬。※全量腎排泄型のため高齢者・腎機能低下時は蓄積し幻覚・せん妄・ミオクローヌスを引き起こすため減量必須。", gId: "c30", cSec: "sec-psy" },
  { name: "ドプス", gen: "ドロキシドパ", cat: "06. 精神神経（ノルアドレナリン前駆物質）", char: "起立性低血圧＆すくみ足を改善する特異な治療薬", desc: "体内でノルアドレナリンに変換。パーキンソン病・シャイ・ドレーガー症候群のすくみ足・起立性低血圧・めまいを改善。夜間・臥位高血圧に注意。", gId: "c30", cSec: "sec-psy" },
  { name: "ミラペックス / ビ・シフロール", gen: "プラミペキソール塩酸塩水和物", cat: "06. 精神神経（非麦角系ドパミンアゴニスト）", char: "ジスキネジア予防の要！若年〜70歳未満の初期第一選択薬", desc: "非麦角系D2/D3受容体作動薬。徐放錠（LA）は1日1回。突発性睡眠（前兆のない急激な眠気・自動車運転厳禁！）、衝動制御障害（病的賭博・過食）に注意。腎排泄型。", gId: "c30", cSec: "sec-psy" },
  { name: "ハルロピ / レキップ", gen: "ロピニロール塩酸塩", cat: "06. 精神神経（非麦角系ドパミンアゴニスト）", char: "貼付剤（ハルロピ）と徐放錠（CR）を持つ主要非麦角系DA", desc: "非麦角系D2受容体作動薬。肝代謝（CYP1A2）。ハルロピテープは24時間安定放出で嚥下困難患者にも有効。突発性睡眠・嘔気・起立性低血圧に注意。", gId: "c30", cSec: "sec-psy" },
  { name: "オンジェンティス", gen: "オピカポン", cat: "06. 精神神経（パーキンソン病COMT阻害）", char: "1日1回就寝前服用の新世代COMT阻害薬！ウェアリングオフのOFF時間を大幅短縮", desc: "末梢COMTを選択的かつ持続的に阻害しL-ドパの脳内移行を増加。1日1回就寝前服用（※食前食後1時間空ける）。代謝物による尿の赤褐色・オレンジ色着色を事前指導。L-ドパ増強によるジスキネジア注意。", gId: "c30", cSec: "sec-psy" },
  { name: "エクフィナ", gen: "サフィナミドメシル酸塩", cat: "06. 精神神経（パーキンソン病MAO-B阻害）", char: "MAO-B阻害＋Naチャネル・グルタミン酸放出抑制のデュアルアクション", desc: "1日1回50〜100mg。ウェアリングオフ改善。抗うつ薬（SSRI/SNRI/三環系）・トラマドール・メジコン等との【セロトニン症候群併用禁忌】に厳重警戒。", gId: "c30", cSec: "sec-psy" },
  { name: "ノウリアスト", gen: "イストラデフィリン", cat: "06. 精神神経（パーキンソン病A2A拮抗）", char: "世界初の非ドパミン新機序！線条体の運動抑制ブレーキを解除", desc: "アデノシンA2A受容体拮抗薬。ドパミン受容体を直接刺激しないためジスキネジアを起こしにくい。⚠️【喫煙でCYP1A2誘導され血中濃度が半減】するため喫煙者は40mgへ増量。", gId: "c30", cSec: "sec-psy" },
  { name: "トレリーフ", gen: "ゾニサミド", cat: "06. 精神神経（パーキンソン病振戦特化）", char: "頑固な手の震え（振戦）を止める！抗てんかん薬の1/10量の低用量設計", desc: "T型Caチャネル遮断・ドパミン合成促進。1日25〜50mg 1日1回（エクセグラン200〜400mgと混同厳禁）。発汗減少による体温上昇・熱中症に注意。", gId: "c30", cSec: "sec-psy" },
  { name: "ニュープロパッチ", gen: "ロチゴチン", cat: "06. 精神神経（非麦角系ドパミンアゴニスト）", char: "24時間安定放出の経皮吸収型！嚥下困難時・朝の早期OFF改善に最適", desc: "非麦角系DA貼付剤。皮膚かぶれ防止のため毎日貼付部位を変更。突発性睡眠（自動車運転厳禁！）、衝動制御障害（病的賭博・過度の買い物）に注意。MRI時は剥がす。", gId: "c30", cSec: "sec-psy" },
  { name: "エブランチルカプセル", gen: "ウラピジル", cat: "2. 高血圧 / 泌尿器・排尿障害", char: "末梢α1遮断＋中枢5-HT1A刺激（高血圧＆前立腺肥大・排尿困難の二刀流）", desc: "末梢α1受容体遮断による血管拡張・前立腺平滑筋弛緩に加え、中枢セロトニン5-HT1A受容体を刺激して交感神経活動を抑制。前立腺肥大症や神経因性膀胱に伴う排尿困難と高血圧の合併に頻出。初回服用時の起立性低血圧（めまい・ふらつき）に注意。カプセル内は徐放性微粒子のため噛み砕き・粉砕不可！", gId: "c2", cSec: "sec-ht" },
  { name: "リスモダン (リスモダンR)", gen: "ジソピラミド", cat: "3. 心不全・循環器 / 抗不整脈薬", char: "Ia群抗不整脈薬（緑内障・前立腺肥大禁忌！重篤な低血糖に厳重警戒）", desc: "Naチャネル・Kチャネル遮断薬。膵K_ATPチャネル遮断作用による【重篤な遷延性低血糖】に注意（高齢・腎機能低下で多発）。強力な抗コリン作用により閉塞隅角緑内障・尿路閉塞（前立腺肥大）は絶対禁忌。QT延長・TdP注意。腎排泄型。リスモダンRカプセルは徐放性製剤のため粉砕・脱カプセル厳禁！", gId: "c3", cSec: "sec-cv" },
  { name: "オグサワ処方", gen: "オーグメンチン＋サワシリン併用", cat: "感染症（成人呼吸器・小児共通）処方ウラ読み", char: "アモキシシリン重複ではない！クラブラン酸下痢を防ぎ耐性菌を叩く黄金比率", desc: "日本のオーグメンチン（2:1）による激烈な下痢を防ぐため、安全なCVA量を維持しつつサワシリンを上乗せして高用量AMPC（成人1500〜2000mg/日、小児70〜90mg/kg/日）を達成する成人市中肺炎・誤嚥性肺炎・動物咬傷・小児中耳炎の合目的処方。", gId: "c24", cSec: "sec-inf" },
// 1. 悪性腫瘍・緩和
  { name: "ティーエスワン (S-1)", gen: "テガフール・ギメラシル・オテラシル", cat: "1. 悪性腫瘍", char: "戦国武将の3人組（主役・ボディガード・胃腸の盾）", desc: "休薬期間厳守の経口抗がん薬。ボディガードの「ギメラシル（DPD阻害）」が腎排泄のため、腎機能低下時は5-FUが蓄積して猛烈な骨髄抑制・下痢を起こす！", gId: "c1", cSec: "sec-onc" },
  { name: "ゼローダ", gen: "カペシタビン", cat: "1. 悪性腫瘍", char: "腫瘍内で5-FUに変わるプロドラッグ", desc: "大腸がん（XELOX等）・乳がんの主力。手足症候群（手のひらや足の裏の赤み・ひび割れ）の予防に保湿剤がセットで出る。", gId: "c1", cSec: "sec-onc" },
  { name: "タグリッソ", gen: "オシメルチニブ", cat: "1. 悪性腫瘍", char: "EGFR変異陽性肺がんのエース", desc: "ざ瘡様皮疹・爪囲炎を防ぐため、初日からステロイド外用薬＋保湿剤＋ミノサイクリン内服（先制治療）がセットになりやすい。間質性肺炎に注意。", gId: "c1", cSec: "sec-onc" },
  { name: "ジプレキサ", gen: "オランザピン", cat: "1. がん / 6. 精神", char: "最強の制吐薬 兼 抗精神病薬（糖尿病禁忌！）", desc: "【カメレオン薬】10〜20mgなら統合失調症・双極性障害。2.5〜5mg（寝る前）で抗がん薬と一緒なら「最強の遅発性悪心・嘔吐止め」！ただし糖尿病患者には絶対禁忌！", gId: "c1", cSec: "sec-onc" },
  { name: "オキシコンチン / オキノーム", gen: "オキシコドン", cat: "1. 悪性腫瘍（緩和）", char: "内服強オピオイドの絶対的スタンダード", desc: "定時薬（オキシコンチン）でベースの痛みを抑え、突発痛にレスキュー（オキノーム：1日量の1/6〜1/10）を使う。便秘対策（スインプロイクや酸化Mg）が必須。", gId: "c1", cSec: "sec-onc" },
  { name: "フェントス / デュロテップ", gen: "フェンタニル", cat: "1. 悪性腫瘍（緩和）", char: "腎不全でも安心＆便秘が少ない貼付型麻薬", desc: "肝代謝で活性代謝物がないため腎機能低下時のオピオイドスイッチング先として最適。貼付部位をカイロ等で温めると過量吸収されて呼吸抑制を起こす点に注意！", gId: "c1", cSec: "sec-onc" },
  { name: "タペンタ", gen: "タペンタドール", cat: "1. 悪性腫瘍（緩和）", char: "オピオイド＋ノルアドレナリン再取り込み阻害の二刀流", desc: "がんによる「ビリビリする神経障害性疼痛」を伴う痛みに抜群。CYPを介さないため薬物相互作用も少ない。", gId: "c1", cSec: "sec-onc" },
  { name: "モルヒネ (MSコンチン/オプソ)", gen: "モルヒネ", cat: "1. 悪性腫瘍（緩和）", char: "がんの「息苦しさ（呼吸困難感）」を和らげるスペシャリスト", desc: "活性代謝物（M6G）が腎排泄のため、腎機能低下患者では傾眠・呼吸抑制を起こしやすく原則回避。", gId: "c1", cSec: "sec-onc" },
  { name: "スインプロイク", gen: "ナルデメジン", cat: "1. 悪性腫瘍（緩和）", char: "腸のオピオイド受容体だけを守る便秘の特効薬", desc: "脳の鎮痛効果は一切邪魔せず、腸管のμ受容体だけをブロックして麻薬による頑固な便秘（OIC）を解消する。", gId: "c1", cSec: "sec-onc" },

  // 2. 高血圧
  { name: "アジルバ", gen: "アジルサルタン", cat: "2. 高血圧症", char: "ARB 7兄弟の中で降圧パワー最強の横綱", desc: "とにかくしっかり血圧を下げたい時のエース。ザクラス（アムロジピンとの配合剤）も頻出。夏場の過度な降圧・立ちくらみに注意。", gId: "c2", cSec: "sec-ht" },
  { name: "ミカルディス", gen: "テルミサルタン", cat: "2. 高血圧症", char: "胆汁排泄100%＆PPAR-γを刺激する腎・メタボの味方", desc: "腎不全でも使いやすく、半減期が24時間と長い。インスリン抵抗性を改善する付加価値を持つARB。", gId: "c2", cSec: "sec-ht" },
  { name: "ニューロタン", gen: "ロサルタン", cat: "2. 高血圧症", char: "URAT1を阻害して尿酸値も下げる唯一のARB", desc: "痛風・高尿酸血症を合併した高血圧患者や、サイアザイド利尿薬による尿酸上昇を打ち消すために選ばれる（プレミネント配合錠など）。", gId: "c2", cSec: "sec-ht" },
  { name: "ノルバスク / アムロジン", gen: "アムロジピン", cat: "2. 高血圧症", char: "半減期36時間！飲み忘れても血圧が跳ねない絶対王者", desc: "Ca拮抗薬の王道。細動脈だけ広げるため、高用量（10mg）では「足首のむくみ」や「歯肉肥厚」が出やすい（むくみに利尿薬は無効！）。", gId: "c2", cSec: "sec-ht" },
  { name: "アテレック", gen: "シルニジピン", cat: "2. 高血圧症", char: "N型Ca遮断で交感神経を鎮め「むくまない・下の血圧を下げる」技巧派", desc: "アムロジピンで足がむくんだ患者の切り替え先No.1！交感神経終末のN型も抑えるため、若年〜中年の「下の血圧が高い拡張期高血圧」や頻脈傾向に極めて有効。輸出細動脈拡張で蛋白尿も抑制。", gId: "c2", cSec: "sec-ht" },
  { name: "アダラートCR", gen: "ニフェジピン徐放錠", cat: "2. 高血圧症", char: "1日2回・最大80mgまで使える重砲（粉砕絶対NG！）", desc: "難治性高血圧や妊娠20週以降の高血圧にも活躍。精密な徐放錠のため、経管栄養等で粉砕すると急激な血圧低下ショックを起こす！", gId: "c2", cSec: "sec-ht" },
  { name: "ミネブロ", gen: "エサキセレノン", cat: "2. 高血圧症", char: "3剤でも下がらない治療抵抗性高血圧＆糖尿病性腎症の切り札（MRA）", desc: "非ステロイド型MRA。女性化乳房が出にくく、早期から糖尿病性腎症の微量アルブミン尿を強力に減らす。ARB等と併用時は高K血症（K≧5.5）チェック必須。eGFR30未満禁忌。", gId: "c2", cSec: "sec-ht" },
  { name: "エンレスト", gen: "サクビトリルバルサルタン", cat: "2. 高血圧 / 4. 心不全", char: "【2021年高血圧適応取得！】ARBを超える降圧と心腎保護（ARNI）", desc: "【カメレオン薬】心不全のFantastic Four筆頭だけでなく、2021年に本態性高血圧症に適応拡大！重症高血圧や早朝高血圧に絶大な降圧効果。ACE阻害薬からの切り替えは血管浮腫防止のため「36時間休薬」が絶対ルール！", gId: "c2", cSec: "sec-ht" },
  { name: "インデラル", gen: "プロプラノロール", cat: "2. 高血圧 / 6. 神経", char: "高血圧以外（片頭痛・手の震え・静脈瘤・あがり症）で大活躍！", desc: "【カメレオン薬】非選択的β遮断薬（喘息禁忌）。若い女性なら「片頭痛予防」、高齢者なら「本態性振戦」、肝硬変なら「門脈圧亢進・食道静脈瘤出血予防」！", gId: "c2", cSec: "sec-ht" },
  { name: "カルデナリン", gen: "ドキサゾシン", cat: "2. 高血圧症", char: "「寝る前1錠」で早朝高血圧（モーニングサージ）を叩くα1遮断薬", desc: "起立性低血圧を防ぐ意味でも就寝前投与が合理的。前立腺肥大症の排尿改善も兼ねる。", gId: "c2", cSec: "sec-ht" },
  { name: "タナトリル / エースコール", gen: "イミダプリル / テムカプリル", cat: "2. 高血圧 / 5. 脳血管", char: "空咳の副作用を逆手に取った「誤嚥性肺炎予防」の守護神", desc: "ACE阻害薬。ブラジキニンとサブスタンスPを増やすため、脳梗塞後の高齢者では「むせ（咳反射・嚥下反射）を改善して誤嚥性肺炎を防ぐ」目的で処方される！", gId: "c5", cSec: "sec-ht" },

  // 3. 糖尿病
  { name: "メトグルコ", gen: "メトホルミン", cat: "3. 糖尿病", char: "インスリン抵抗性改善の主役（造影剤前後48時間は休薬！）", desc: "肥満2型糖尿病の第一選択（産婦人科では多嚢胞性卵巣症候群PCOSにも使用）。ヨード造影剤検査の前後48時間休薬、eGFR30未満禁忌、シックデイ休薬（乳酸アシドーシス予防）が鉄則！", gId: "c3", cSec: "sec-dm" },
  { name: "フォシーガ / ジャディアンス", gen: "ダパグリフロジン / エンパグリフロジン", cat: "3. 糖尿病 / 4. 心 / 9. 腎", char: "糖尿病・慢性心不全・CKDのすべてを救う三冠王（SGLT2阻害薬）", desc: "【カメレオン薬】血糖値が正常でも、心不全やCKDの予後改善薬として10mg固定で処方される！絶食・手術前・極端な糖質制限時は「正常血糖ケトアシドーシス」に厳戒態勢！", gId: "c3", cSec: "sec-dm" },
  { name: "トラゼンタ / テネリア", gen: "リナグリプチン / テネリグリプチン", cat: "3. 糖尿病", char: "腎機能がどれだけ悪くても減量不要なDPP-4阻害薬コンビ", desc: "胆汁排泄（または肝腎両排泄）のため、透析患者まで同じ量で使える。高齢・CKD合併患者の強い味方。", gId: "c3", cSec: "sec-dm" },
  { name: "ジャヌビア / グラクティブ", gen: "シタグリプチン", cat: "3. 糖尿病", char: "最も処方される王道DPP-4阻害薬（腎機能で減量監査！）", desc: "腎排泄型のため、中等度腎機能低下では25mg、重度では12.5mgへの減量監査が必要。", gId: "c3", cSec: "sec-dm" },
  { name: "リベルサス", gen: "経口セマグルチド", cat: "3. 糖尿病", char: "唯一の飲むGLP-1製剤（起床時・水120mL・30分絶飲食！）", desc: "強力な血糖降下と体重減少効果を持つが、飲み方のルールを1つでも破ると吸収率がゼロになる。湿気にも弱いため一包化NG！", gId: "c3", cSec: "sec-dm" },
  { name: "マンジャロ / オゼンピック / トルリシティ", gen: "チルゼパチド / セマグルチド / デュラグルチド", cat: "3. 糖尿病", char: "週1回皮下注で強力に血糖と体重を落とすインクレチン注射", desc: "トルリシティは針が見えず高齢者に優しい。マンジャロはGIP/GLP-1のデュアル作用で最強クラスの減量・血糖改善効果を持つ（JDS2024最前線）。", gId: "c3", cSec: "sec-dm" },
  { name: "ボグリボース / セイブル", gen: "ボグリボース / ミグリトール", cat: "3. 糖尿病", char: "必ず「食直前」に飲む糖吸収ストッパー（低血糖時はブドウ糖必須！）", desc: "α-グルコシダーゼ阻害薬。SU薬やインスリンと併用中に低血糖が起きたら、普通の砂糖（二糖類）は分解できず効かないため、必ず「ブドウ糖」を摂らせる！", gId: "c3", cSec: "sec-dm" },

  // 4. 心疾患 & 5. 脳血管障害
  { name: "メインテート / アーチスト", gen: "ビソプロロール / カルベジロール", cat: "4. 心疾患 / 2. 高血圧", char: "過労死寸前の心臓を休ませるβ遮断薬の2大巨頭（頻脈・拡張期高血圧にも）", desc: "心不全（HFrEF）では超少量から開始して少しずつ増量。メインテートはβ1選択性が高く頻脈や若年下の血圧が高い人に優れ、アーチストはα1遮断も併せ持ち血管も広げる（喘息禁忌）。", gId: "c4", cSec: "sec-ht" },
  { name: "アルダクトンA / セララ", gen: "スピロノラクトン / エプレレノン", cat: "4. 心疾患", char: "おしっこを出すためではなく「心臓の線維化を防ぐ」守護薬", desc: "【カメレオン薬】心不全で25mg等の少量出ている時は「心筋リモデリング抑制（生命予後改善）」が目的！「利尿薬です」と説明して自己中断させないよう注意。", gId: "c4", cSec: "sec-ht" },
  { name: "エリキュース / リクシアナ", gen: "アピキサバン / エドキサバン", cat: "4. 心疾患 / 5. 脳血管", char: "心房細動の脳塞栓予防に選ばれるDOACの2強", desc: "エリキュースは1日2回で血中濃度の谷が浅く、腎機能低下時も減量して使いやすい。リクシアナは1日1回服薬でアドヒアランス最高。", gId: "c4", cSec: "sec-cv" },
  { name: "イグザレルト / プラザキサ", gen: "リバーロキサバン / ダビガトラン", cat: "4. 心疾患 / 5. 脳血管", char: "DOACの個性派（食直後服用 / 中和剤プリズバインドあり）", desc: "イグザレルトは空腹時だと吸収が悪いため必ず「食後服用」。プラザキサは直接トロンビン阻害薬で特異的中和剤があるが、吸湿性が強いためPTPシート管理必須。", gId: "c4", cSec: "sec-cv" },
  { name: "バイアスピリン", gen: "低用量アスピリン", cat: "4. 心 / 5. 脳血管", char: "川の流れが速い動脈を守る「抗血小板薬」の元祖", desc: "心筋梗塞や非心原性脳梗塞の再発予防。胃潰瘍予防にPPI併用が推奨される。100mgは抗血小板、330〜500mgなら解熱鎮痛という用量の違いを見逃すな！", gId: "c5", cSec: "sec-cv" },
  { name: "キャブピリン配合錠", gen: "ボノプラザン 10mg / アスピリン 100mg", cat: "4. 心 / 5. 脳血管 / 消化器", char: "P-CAB＋腸溶性アスピリンの有核二層錠！粉砕・簡易懸濁は絶対厳禁！", desc: "胃・十二指腸潰瘍の【既往】がある患者のアスピリン潰瘍再発抑制に唯一適応。外層ボノプラザンが初回から強酸をブロックし、内核腸溶性アスピリンが小腸で溶出。粉砕すると胃内でアスピリンが溶出し重篤な胃出血を起こすため粉砕・一包化厳禁！", gId: "c5", cSec: "sec-cv" },
  { name: "タケルダ配合錠", gen: "ランソプラザール 15mg / アスピリン 100mg", cat: "4. 心 / 5. 脳血管 / 消化器", char: "PPI＋腸溶性低用量アスピリン配合錠（有核錠のため粉砕不可）", desc: "低用量アスピリン服用時の潰瘍再発抑制。先行PPI合剤。キャブピリンと異なりランソプラザールはCYP2C19遺伝子多型により代謝速度・抑制力に個体差あり。粉砕不可。", gId: "c5", cSec: "sec-cv" },
    { name: "ニトロペン (舌下錠)", gen: "ニトログリセリン", cat: "4. 虚血性心疾患", char: "狭心症発作の絶対的レスキュー（立って飲むな・飲み込むな！）", desc: "冠動脈拡張と静脈還流量低減で発作を速効寛解。血圧低下による失神防止のため必ず「座るか横になって」舌下投与。飲み込むと肝初回通過効果で無効！5分間隔で2〜3回使っても治まらない胸痛は即119番（ACS疑い）！重度大動脈弁狭窄症（AS）では失神ショックの恐れがあり原則回避。", gId: "c4", cSec: "sec-cv" },
  { name: "ヘルベッサー", gen: "ジルチアゼム塩酸塩", cat: "4. 虚血性心疾患 / 不整脈", char: "冠攣縮性狭心症の主役 兼 上室性不整脈レート調整のCa拮抗薬", desc: "冠動脈平滑筋を強力に弛緩しスパスム（痙攣）を阻止。夜間〜早朝発作を防ぐため夕食後〜就寝前投与が合理的。房室伝導を抑えるため心房細動のレートコントロールにも頻用。非選択的β遮断薬単独は冠攣縮を誘発するため禁忌！", gId: "c4", cSec: "sec-cv" },
  { name: "ワーファリン", gen: "ワルファリンカリウム", cat: "4. 弁膜症 / 不整脈", char: "機械弁置換術後の絶対的守護神（DOAC絶対禁忌！PT-INR管理）", desc: "機械弁置換後や中等度以上僧帽弁狭窄症（MS）ではDOACは臨床試験で血栓・出血が激増し「絶対禁忌」！ワルファリンのみが適応。納豆・クロレラ・青汁のビタミンK厳禁。併用薬相互作用（ケアラム併用禁忌など）に厳重警戒。", gId: "c4", cSec: "sec-cv" },
  { name: "アンカロン", gen: "アミオダロン塩酸塩", cat: "4. 不整脈", char: "致死性不整脈をねじ伏せる最強のⅢ群抗不整脈薬（副作用トリプル毒性に注意！）", desc: "心室細動（Vf）・心室頻拍（VT）や難治性心房細動の切り札。ヨウ素を含むため「甲状腺機能異常（TSH定期採血）」「間質性肺炎（乾性咳嗽・SpO2低下）」「角膜色素沈着」のモニタリングが必須。半減期が数週〜1ヶ月以上と超長い。", gId: "c4", cSec: "sec-cv" },
  { name: "カムジオス", gen: "マバカムテン", cat: "4. 心筋症（新薬）", char: "閉塞性肥大型心筋症（HOCM）の初の心筋ミオシン阻害薬", desc: "過剰なアクチン・ミオシン架橋形成を抑制し左室流出路閉塞を劇的に解除する新薬。過度な心収縮抑制による心不全悪化を防ぐため定期心エコー（LVEF測定）とCYP2C19相互作用監査が必須。", gId: "c4", cSec: "sec-cv" },
    { name: "アドシルカ / レバチオ", gen: "タダラフィル / シルデナフィル", cat: "4. 肺高血圧症 / 循環器", char: "肺動脈のPDE5を選択的に阻害し血管拡張！硝酸薬と絶対併用禁忌！", desc: "肺動脈平滑筋のcGMPを増やして血管拡張。タダラフィル（アドシルカ 40mg）は1日1回、シルデナフィル（レバチオ 20mg）は1日3回。ニトロペン等の硝酸薬と併用すると急激な致死的血圧低下を起こすため絶対禁忌！sGC刺激薬（アデムパス）との併用も禁忌。", gId: "c4", cSec: "sec-cv" },
  { name: "アデムパス", gen: "リオシグアト", cat: "4. 肺高血圧症（PAH / CTEPH）", char: "CTEPH（第4群）にも唯一使える可溶性グアニル酸シクラーゼ（sGC）刺激薬", desc: "内因性NOに依存せず直接sGCを刺激してcGMPを産生し強力に肺血管拡張。肺動脈性（PAH）だけでなく慢性血栓塞栓性肺高血圧症（CTEPH）に保険適用。PDE5阻害薬（アドシルカ等）や硝酸薬とは絶対併用禁忌！喫煙により血中濃度が激減するため禁煙必須。催奇形性禁忌。", gId: "c4", cSec: "sec-cv" },
  { name: "オプスミット / ヴォリブリス", gen: "マシテンタン / アンブリセンタン", cat: "4. 肺高血圧症（ERA）", char: "強力な血管収縮物質エンドセリンを阻害する主力経口薬（催奇形性禁忌！）", desc: "エンドセリン受容体拮抗薬（ERA）。早期からPDE5阻害薬と2剤併用（Initial Dual Combination）される。ボセンタン（トラクリア）と比べ肝障害リスクが低減されているが、貧血・浮腫に注意。胎児毒性があるため妊婦禁忌・避妊指導必須。", gId: "c4", cSec: "sec-cv" },
  { name: "ウプトラビ / フローラン", gen: "セレキシパグ / エポプロステノール", cat: "4. 肺高血圧症（PGI2経路）", char: "プロスタサイクリン経路を刺激する救命薬（フローランは中断絶対厳禁！）", desc: "ウプトラビは経口PGI2受容体作動薬（下痢・頭痛・顎痛の用量調節）。フローラン（持続静注）は最重症PAHの切り札で半減期3〜5分。ポンプ閉塞・液漏れによる急な投与中断は反跳性肺高血圧発作（リバウンド）で死に至るため絶対厳禁！専用溶解液管理必須。", gId: "c4", cSec: "sec-cv" },
  { name: "プラビックス / エフィエント", gen: "クロピドグレル / プラスグレル", cat: "4. 心 / 5. 脳血管", char: "ステント留置後の血栓を防ぐADP受容体遮断薬", desc: "ステント留置後はバイアスピリンと2剤併用（DAPT）される。クロピドグレルはCYP2C19遺伝子多型で効きにくい人がいるが、プラスグレルは個体差が少ない。", gId: "c5", cSec: "sec-cv" },

  // 6. 精神神経
  { name: "デジレル / レスリン", gen: "トラゾドン", cat: "6. 精神神経", char: "うつ病の薬だが、実際は「依存のない安全な睡眠薬」として大活躍！", desc: "【カメレオン薬】25〜50mgの少量寝る前投与は高齢者の不眠・夜間せん妄対策の隠れた定番。ふらつき・転倒リスクが極めて低い。", gId: "c6", cSec: "sec-psy" },
  { name: "リフレックス / レメロン", gen: "ミルタザピン", cat: "6. 精神神経", char: "「眠気と食欲増進」を逆手に取った、やせ衰えた高齢不眠うつの救世主", desc: "NaSSA。飲み始めに強烈な眠気が出るため夕食後〜就寝前に飲む。抗コリン作用が少なく、体重減少・食欲不振・不眠を伴ううつ病に劇的に効く。", gId: "c6", cSec: "sec-psy" },
  { name: "デパケン", gen: "バルプロ酸ナトリウム", cat: "6. 精神神経 / 12. 疼痛", char: "てんかん・躁病・片頭痛予防の三刀流（催奇形性に厳重警戒！）", desc: "【カメレオン薬】用量と血中濃度モニタリング（TDM）が肝。若年女性の妊娠可能年齢では催奇形性・神経管閉鎖障害リスクのため原則回避。", gId: "c6", cSec: "sec-psy" },
  { name: "デエビゴ / ベルソムラ", gen: "レンボレキサント / スボレキサント", cat: "6. 精神神経", char: "覚醒のスイッチをOFFにする新世代オレキシン受容体拮抗薬", desc: "筋弛緩作用や依存性がなく、高齢者の夜間転倒リスクが激減。ベルソムラはCYP3A4阻害薬（クラリスロマイシン等）と併用禁忌！デエビゴは悪夢に注意。", gId: "c6", cSec: "sec-psy" },

  // 7. 免疫・アレルギー
  { name: "リウマトレックス", gen: "メトトレキサート (MTX)", cat: "7. 免疫アレルギー", char: "関節リウマチの絶対的アンカードラッグ（週1〜2日服用！）", desc: "毎日飲んだら命に関わる骨髄抑制！休薬期間（週5日）を絶対に守る。副作用（口内炎・肝障害）が出たら48時間後に「フォリアミン（葉酸）」をレスキュー。", gId: "c7", cSec: "sec-imm" },
  { name: "レルベア / シムビコート", gen: "ビランテロール・フルチカゾン / ブデソニド・ホルモテロール", cat: "7. 免疫アレルギー", char: "喘息・COPDの気道炎症を鎮める吸入ステロイド＋気管支拡張薬", desc: "吸入後の「ブクブクうがい＋ガラガラうがい」は嗄声（声枯れ）と口腔カンジダ症予防に必須！シムビコートは発作時の頓用追加（SMART療法）が可能。", gId: "c7", cSec: "sec-imm" },
  { name: "ビラノア / デザレックス / ルパフィン", gen: "ビラスチン / デスロラタジン / ルパタジン", cat: "7. 免疫アレルギー", char: "自動車運転制限のない第2世代抗ヒスタミン薬", desc: "ビラノアは空腹時服用（食後だと効果半減）。ルパフィンは抗PAF作用も併せ持つ強力型だが運転注意。", gId: "c7", cSec: "sec-imm" },

  // 8. 感染症
  { name: "サワシリン / オーグメンチン", gen: "アモキシシリン / クラブランク酸配合", cat: "8. 感染症", char: "外来感染症治療の王道ペニシリン系（時間依存性抗菌薬）", desc: "PK/PDパラメータは「%T>MIC」。1回量をケチらず、しっかり1日3〜4回等間隔で飲むことが耐性菌を防ぐカギ。オーグメンチンは下痢を起こしやすい。", gId: "c8", cSec: "sec-inf" },
  { name: "クラビット", gen: "レボフロキサシン", cat: "8. 感染症", char: "切れ味鋭いニューキノロン（安易な乱用は耐性菌の温床！）", desc: "濃度依存性（Cmax/MIC）。金属イオン（Mg/Al/Fe/Ca）と合体してキレート沈殿を起こし吸収率が激減するため、マグミットや鉄剤と2時間以上あける！", gId: "c8", cSec: "sec-inf" },

  // 9. 腎・泌尿器
  { name: "サムスカ", gen: "トルバプタン", cat: "9. 腎・泌尿器 / 4. 心", char: "電解質を捨てずに水だけを絞り出す水利尿薬（V2拮抗薬）", desc: "ループ利尿薬でNaが下がって引けない難治性浮腫・腹水に劇的効果。急激な血清Na上昇（橋中心髄鞘崩壊症）を防ぐため入院下導入が原則。", gId: "c9", cSec: "sec-ckd" },
  { name: "ダイアモックス", gen: "アセタゾラミド", cat: "9. 腎 / 14. 眼科", char: "利尿薬の仮面を被った「緑内障・高山病・睡眠時無呼吸」の特効薬", desc: "【カメレオン薬】炭酸脱水酵素阻害。房水産生を抑えて急性緑内障発作を救い、代謝性アシドーシスを起こして呼吸中枢を刺激し高山病を防ぐ！", gId: "c9", cSec: "sec-ckd" },
  { name: "ハルナール", gen: "タムスロシン", cat: "9. 腎・泌尿器", char: "前立腺肥大症の尿道を広げるα1遮断薬（女性に出たら尿管結石！）", desc: "【カメレオン薬】女性に出ている時は尿管結石を自然排出させる適応外使用！", gId: "c9", cSec: "sec-ckd" },

  // 10. 脂質・骨粗鬆症
  { name: "クレストール / リピトール", gen: "ロスバスタチン / アトルバスタチン", cat: "10. 脂質異常症", char: "LDLを強力に叩き落とすストロングスタチン2強", desc: "心筋梗塞二次予防ではLDL<70を目指す。筋肉痛・脱力感・赤褐色尿は「横紋筋融解症」の初期症状！グレープフルーツ（アトルバスタチン）に注意。", gId: "c10", cSec: "sec-ckd" },
  { name: "ボナロン / フォサマック", gen: "アレンドロン酸", cat: "10. 骨粗鬆症", char: "起床時・コップ1杯の水・30分横にならない！を徹底するBP製剤", desc: "吸収率1%未満。ミネラルウォーターの硬水（Ca含有）で飲むと吸収ゼロ！食道潰瘍を防ぐため服用後30分は絶対に横臥しない。抜歯前のARONJ確認必須。", gId: "c10", cSec: "sec-ckd" },
  { name: "アレジオンLX点眼液", gen: "エピナスチン塩酸塩", cat: "25. アレルギー性結膜炎", char: "1日2回で効果持続！コンタクトレンズを装用したまま直接点眼できる最強点眼薬", desc: "塩化ベンザルコニウム不含のためソフトコンタクト装用中もそのまま点眼OK。朝・夕の1日2回で日中の目のかゆみを完全ブロック。", gId: "c14", cSec: "sec-extra" },
  { name: "ベピオゲル / ローション", gen: "過酸化ベンゾイル（BPO）", cat: "34. 尋常性ざ瘡（ニキビ）", char: "耐性菌が出ない酸化殺菌エース！衣類・タオルの漂白（脱色）に厳重注意", desc: "アクネ菌を死滅させ毛穴詰まりを解除。髪や枕カバー、衣類、タオルに付着すると白く色が抜けるため手洗い徹底。初期の乾燥赤みには保湿併用。", gId: "c16", cSec: "sec-imm" },
  { name: "ディフェリンゲル", gen: "アダパレン", cat: "34. 尋常性ざ瘡（ニキビ）", char: "白ニキビの毛穴詰まりを根本解除！妊婦・妊娠希望女性には催奇形性のため絶対禁忌", desc: "表皮角化を正常化。使い始めの2〜4週間に乾燥・落屑・赤みが高率に出るが保湿で乗り切れば改善。妊婦禁忌。", gId: "c16", cSec: "sec-imm" },
  { name: "エピデュオゲル", gen: "過酸化ベンゾイル＋アダパレン", cat: "34. 尋常性ざ瘡（ニキビ）", char: "ニキビ外用の最強二刀流合剤！毛穴詰まり解除＋殺菌で中等度〜重症に劇的効果", desc: "ベピオとディフェリンの合剤。効果最強だが刺激感（赤み・乾燥）も強いため保湿剤先行塗布を指導。妊婦禁忌・漂白注意。", gId: "c16", cSec: "sec-imm" },
  { name: "デュアック配合ゲル", gen: "過酸化ベンゾイル＋クリンダマイシン", cat: "34. 尋常性ざ瘡（ニキビ）", char: "赤ニキビ急性期の火消し合剤！要冷蔵保存（2〜8℃）＆漂白注意", desc: "BPOがクリンダマイシン耐性菌の出現を防止。要冷蔵保存。急性期の炎症が引いたら維持薬（ベピオ等）へステップダウン。", gId: "c16", cSec: "sec-imm" },
  { name: "ゼビアックスローション", gen: "オゼノキサシン", cat: "34. 尋常性ざ瘡（ニキビ）", char: "1日1回塗布の新規キノロン外用薬！耐性アクネ菌にも高い抗菌力", desc: "耐性アクネ菌・黄色ブドウ球菌に強力。1日1回でアドヒアランス良好。化膿が治まったら漫然投与せず終了。", gId: "c16", cSec: "sec-imm" },
  { name: "ダラシンTゲル / ローション", gen: "クリンダマイシンリン酸エステル", cat: "34. 尋常性ざ瘡（ニキビ）", char: "赤ニキビの標準外用抗菌薬！単剤連用での耐性菌増加に注意（BPO併用推奨）", desc: "1日2回塗布。アクネ菌の蛋白合成を阻害して炎症性皮疹を沈静化。耐性アクネ菌の出現を防ぐためデュアック（BPO配合）やベピオ併用が基本。漫然投与せず軽快後は中止。", gId: "c16", cSec: "sec-imm" },
  { name: "アクアチム軟膏 / クリーム / ローション", gen: "ナジフロキサシン", cat: "34. 尋常性ざ瘡（ニキビ）", char: "キノロン系外用抗菌薬！軟膏・クリーム・ローションで患部の乾燥・部位に合わせて選択", desc: "1日2回塗布。DNAジャイレースを阻害し強力な殺菌作用を発揮。化膿性炎症を速やかに鎮火。刺激症状や耐性菌化を防ぐため急性期に限定して使用。", gId: "c16", cSec: "sec-imm" },
  { name: "ビブラマイシン錠", gen: "ドキシサイクリン塩酸塩水和物", cat: "34. 尋常性ざ瘡（ニキビ） / 感染症", char: "ニキビ経口抗菌薬の推奨度A！ミノマイシンでめまいが出る患者の最有力選択肢＆食道潰瘍注意", desc: "テトラサイクリン系。ミノマイシンと同等の抗炎症・抗菌力を持ちながら前庭障害（めまい・ふらつき）が極めて少ない。コップ1杯以上の多めの水で服用し、食道潰瘍を防ぐため服用後30分は横臥禁止。原則3ヶ月以内に中止。金属イオンキレート注意。", gId: "c16", cSec: "sec-imm" },
  { name: "ネイリンカプセル", gen: "ホスラブコナゾール", cat: "30. 爪白癬（爪水虫）", char: "1日1回1カプセルを12週間内服で治癒！定期的な肝機能検査（AST/ALT）必須", desc: "爪母から爪全体に強力浸透。12週間内服で高い完全治癒率。重篤な肝障害を防ぐため投与前および投与中の定期採血必須。妊婦禁忌。", gId: "c16", cSec: "sec-extra" },
  { name: "クレナフィン爪外用液", gen: "エフィナコナゾール", cat: "30. 爪白癬（爪水虫）", char: "厚い爪を透過する外用爪水虫薬！新しい健康な爪が生え変わるまで毎日塗布", desc: "ハケ一体型で爪全体・爪周囲・爪先に塗布。内服が使えない肝障害や高齢者にも安全。爪の生え変わり（半年〜1年）まで継続。", gId: "c16", cSec: "sec-extra" },
  { name: "ベオーバ", gen: "ビベグロン", cat: "22. 過活動膀胱（OAB）", char: "選択的β3作動薬！CYP2D6阻害がなく多剤併用の高齢者でも使いやすいOAB第一選択", desc: "膀胱平滑筋を弛緩させ蓄尿機能を改善。ベタニスと異なりCYP2D6阻害や生殖年齢への制限がなく相互作用が少ない。", gId: "c9", cSec: "sec-ckd" },
  { name: "メノエイドコンビパッチ", gen: "エストラジオール・酢酸ノルエチステロン", cat: "44. 更年期障害", char: "週2回貼るだけ！肝初回通過回避で経口ピルより血栓・脂質リスクが低いHRT経皮パッチ", desc: "ホットフラッシュや発汗、情緒不安定を劇的改善。週2回下腹部に貼付。乳がん・子宮内膜がん既往や血栓症には禁忌。", gId: "c13", cSec: "sec-extra" },
  { name: "加味逍遙散", gen: "漢方エキス（ツムラ24等）", cat: "44. 更年期障害 / 漢方", char: "更年期のイライラ・のぼせ・自律神経失調を鎮める第一選択漢方方剤", desc: "虚弱〜中等度体質。ホットフラッシュ、不安、不眠に特効。甘草含有のため長期連用時の低カリウム血症・浮腫に注意。", gId: "c13", cSec: "sec-extra" },
  { name: "タリビッド耳科用液", gen: "オフロキサシン", cat: "46. 急性中耳炎・外耳炎", char: "点耳前の「体温加温」が絶対鉄則！冷たいまま差すと激しいめまい・嘔気（カロリック反応）", desc: "急性外耳炎・中耳炎に1回6〜10滴点耳後10分耳浴。容器を手で握って温めてから点耳する指導が事故防止に不可欠。", gId: "c29", subId: "c29-ear", cSec: "sec-extra" },
  { name: "メリスロン", gen: "ベタヒスチンメシル酸塩", cat: "46. めまい（眩暈・内耳循環）", char: "内耳微小循環を増強する処方実績No.1！眠気なし＆気管支喘息・消化性潰瘍既往注意", desc: "ヒスタミン様H1作動＋H3遮断。内耳血管を拡張し前庭神経核のアンバランスを是正。眠気がないため運転・就労者に最適。ヒスタミン作用による喘息悪化・胃酸分泌に注意。", gId: "c29", cSec: "sec-extra" },
  { name: "セファドール", gen: "ジフェニドール塩酸塩", cat: "46. めまい（眩暈・前庭神経調整）", char: "前庭神経の異常興奮を遮断＋椎骨動脈血流改善！抗コリン作用（緑内障・前立腺肥大注意）", desc: "前庭神経路の求心性インパルスを直接遮断しめまい中枢を鎮静。椎骨動脈血流も改善し内耳・循環不全両方に有効。抗コリン作用併有のため閉塞隅角緑内障・前立腺肥大症に注意。眠気注意。", gId: "c29", cSec: "sec-extra" },
  { name: "イソバイドシロップ", gen: "イソソルビド", cat: "46. めまい（メニエール病・浸透圧利尿）", char: "メニエール病の内リンパ水腫を直接排泄！「冷やす・炭酸水割り」激マズ対策指導", desc: "高浸透圧利尿薬。内耳リンパ腔の余分な水分を血中へ引き抜いて利尿し、回転性めまい・低音難聴・耳閉感を改善。激マズのため冷蔵庫で冷やす・炭酸水やレモン水で1:1に割る指導が命。", gId: "c29", cSec: "sec-extra" },
  { name: "アデホスコーワ", gen: "アデノシン三リン酸二ナトリウム（ATP）", cat: "46. めまい・耳鳴り・難聴（代謝賦活）", char: "内耳有毛細胞と前庭神経を蘇らせるATPエネルギーチャージ！顆粒吸湿注意", desc: "内耳・脳血管拡張＋生体エネルギーATP供給。虚血で疲弊した内耳組織の代謝を活性化。耳鳴り・難聴を伴うめまいの定番併用薬。下痢など消化器症状、顆粒の吸湿に注意。", gId: "c29", cSec: "sec-extra" },
  { name: "苓桂朮甘湯", gen: "漢方エキス（ツムラ39等）", cat: "46. めまい（立ちくらみ・起立性低血圧 / 漢方）", char: "立ちくらみ・ふわふわめまい・動悸・胃内停水の第一選択！水毒をさばき上気を降ろす", desc: "苓桂朮甘湯。体内の水分偏在（水毒）を解消し、上気（のぼせ・動悸・ふらつき）を下ろす。起立性低血圧や起立性調節障害（OD）に著効。甘草含有のため偽アルドステロン症注意。", gId: "c29", cSec: "sec-extra" },
  { name: "ボラザG軟膏", gen: "トリベノシド・リドカイン", cat: "50. 痔核・裂肛", char: "非ステロイド性注入軟膏！内痔核は注入、外痔核・切れ痔は塗布の二刀流", desc: "創傷治癒促進＋局所麻酔による鎮痛。ステロイド不含のため長期維持にも安全。便秘のいきみ対策（酸化Mg）併用。", gId: "c26", cSec: "sec-extra" },
  { name: "ヘモリンガル舌下錠", gen: "静脈血管叢エキス", cat: "50. 内痔核", char: "飲み込まず舌の下で溶かす内痔核薬！痔静脈叢のうっ血・腫れを改善", desc: "空腹時に舌下崩壊させて吸収。飲み込むと効果が激減するため舌下投与を厳守指導。排便コントロールと併用。", gId: "c26", cSec: "sec-extra" },
  { name: "アメナリーフ", gen: "アメナメビル", cat: "63. 単純ヘルペス（PIT） / 45. 帯状疱疹", char: "ヘルペスPITの最新主役！1回1200mg食後内服で1回完結（腎機能減量不要・軽食必須）", desc: "初期症状6時間以内に1回1200mg（200mg 6錠）食後単回服用。1回飲むだけでPIT完了。腎排泄でないため腎障害でも減量不要。空腹時服用は吸収が落ちるため軽食を摂らせる。帯状疱疹は1日1回400mg食後。", gId: "c16", cSec: "sec-extra" },
  { name: "ファムビル", gen: "ファムシクロビル", cat: "63. 単純ヘルペス（PIT）", char: "ヘルペス再発の切り札！ピリピリ初期症状から6時間以内に自己判断服用（1回1000mg計2回完結）", desc: "再発ヘルペス患者にあらかじめ処方。初期症状から6時間以内に1回1000mg、12時間後に2回目を飲んで1日で終了。水疱化を阻止。", gId: "c16", cSec: "sec-extra" },
  { name: "サンコバ点眼液", gen: "シアノコバラミン", cat: "65. 眼精疲労", char: "鮮やかな赤色ビタミンB12点眼！毛様体筋の疲労を回復させスマホ・PC眼精疲労を改善", desc: "ピント調節麻痺・VDT作業疲労に1回1〜2滴1日3〜5回点眼。光分解を防ぐため遮光袋保管を必ず指導。", gId: "c14", cSec: "sec-extra" },
  { name: "レグナイト", gen: "ガバペンチンエナカルビル", cat: "73. むずむず脚症候群（RLS）", char: "「夕食後」服用が絶対鉄則！オーグメンテーションが極めて少ないRLS第一選択薬", desc: "夜間の下肢むずむず感を抑える。必ず夕食後に服用（空腹時だと吸収激減）。腎排泄型。血清フェリチン低値（<50）なら鉄補充併用。", gId: "c6", cSec: "sec-extra" },
  { name: "オパルモン / プロレナール", gen: "リマプロストアルファデクス", cat: "79. 脊柱管狭窄症 / 閉塞性動脈硬化症", char: "馬尾神経血流改善のPGE1誘導体！「少し歩くと足がしびれて前かがみで休むと治る（間欠跛行）」に特効", desc: "脊柱管狭窄症の神経性間欠跛行に1回5μg 1日3回食後内服。抗血栓作用のため出血注意。吸湿性に注意。", gId: "c12", cSec: "sec-extra" },
  { name: "アコファイド", gen: "アコチアミド", cat: "67. 機能性ディスペプシア（FD）", char: "世界初のFD治療薬！アセチルコリン分解を抑え胃運動を改善（「食前」服用必須！）", desc: "胃もたれ・早期膨満感に1回100mg 1日3回食前服用。食後だと効果が落ちるため食前投与を指導。", gId: "c11", cSec: "sec-ckd" },
  { name: "ミニリンメルト", gen: "デスモプレシン酢酸塩水和物", cat: "86. 夜尿症（おねしょ）", char: "夜尿を直接減らす抗利尿ホルモン製剤！「就寝前2〜3時間飲水制限」で水中毒を厳重防止", desc: "就寝直前に舌下崩壊。服用前2〜3時間および就寝中の飲水制限厳守。頭痛・嘔吐・浮腫は低Na血症水中毒の初期徴候。", gId: "c18", cSec: "sec-extra" },
  { name: "ドボベット", gen: "カルシポトリオール・ベタメタゾン", cat: "92. 尋常性乾癬", char: "乾癬外用の標準配合剤！角化抑制VitD3＋強力ステロイドの相乗効果（高Ca血症注意）", desc: "1日1回患部に塗布。フォーム剤はよく振る（火気厳禁）。週上限90g（フォーム週60g）。エディロール併用時Ca値注意。", gId: "c16", cSec: "sec-imm" },
  { name: "オテズラ", gen: "アプレミラスト", cat: "92. 尋常性乾癬", char: "注射を避けたい乾癬患者の経口PDE4阻害薬！初期の下痢・悪心を漸増投与で乗り切る", desc: "5日間のスターター漸増パックで開始。下痢・悪心の初期説明必須。抑うつ気分・体重減少のモニタリング。", gId: "c16", cSec: "sec-imm" },
  { name: "チャンピックス", gen: "バレニクリン", cat: "98. ニコチン依存症（禁煙治療）", char: "離脱症状とタバコの美味しさを両面遮断！自動車運転等は絶対禁止の禁煙治療薬", desc: "禁煙開始1週間前から服用開始。12週間プログラム。食後服用で悪心を軽減。傾眠・めまいのため自動車運転等は終日禁止。", gId: "c11", cSec: "sec-extra" },
  { name: "ビラノア", gen: "ビラスチン", cat: "28. 花粉症・鼻炎", char: "眠気ゼロで自動車運転OK！空腹時（就寝前または起床時）服用が絶対鉄則の最強キレ味", desc: "脳内H1受容体占拠率ほぼゼロ。食後だと吸収率が40%激減するため空腹時厳守。1日1回服用で即効性と持続性に優れる。", gId: "c28", cSec: "sec-imm" },
  { name: "ルパフィン", gen: "ルパタジン", cat: "28. 花粉症・鼻炎", char: "ヒスタミンH1＋PAFのデュアルブロック！頑固な鼻づまりに最強だが運転絶対不可", desc: "血小板活性化因子PAFを叩き鼻粘膜浮腫を劇的解除。食事の影響なし。眠気が出るため自動車運転等危険作業は終日禁止。", gId: "c28", cSec: "sec-imm" },
  { name: "デザレックス", gen: "デスロラタジン", cat: "28. 花粉症・鼻炎", char: "眠気ゼロで自動車運転OK！食事の影響を受けずいつでも飲める快適な第2世代", desc: "クラリチンの活性代謝物。1日1回いつでも内服可能。肝代謝影響が少なく多剤併用でも使いやすい。", gId: "c28", cSec: "sec-imm" },
  { name: "ゾフルーザ", gen: "バロキサビルマルボキシル", cat: "27. インフルエンザ", char: "1回飲むだけで治療完了！ウイルス排出停止が最速の新規エンドヌクレアーゼ阻害薬", desc: "発症48時間以内に単回経口投与。ウイルス増殖を瞬時に停止。耐性アミノ酸変異に留意。多価金属イオン併用時キレート注意。", gId: "c27", cSec: "sec-inf" },
  { name: "イナビル", gen: "ラニナミビルオクタン酸エステル", cat: "27. インフルエンザ", char: "薬局で1回吸入して治療完了！肺局所に留まり飲み忘れゼロの長時間型NA阻害薬", desc: "発症48時間以内に1回吸入（成人40mg）。十分な吸気力が必要。解熱しても発症後5日＋解熱後2日の出席停止基準を指導。", gId: "c27", cSec: "sec-inf" },
  { name: "PL配合顆粒 / ピーエイ", gen: "サリチルアミド・アセトアミノフェン等", cat: "27. かぜ症候群", char: "総合感冒薬の王道！抗コリン作用により「緑内障・前立腺肥大症に禁忌！」", desc: "プロメタジンの抗コリン作用で口渇・尿閉・眼圧上昇。アスピリン喘息禁忌。他科アセトアミノフェンとの重複過量投与を厳戒チェック。", gId: "c27", cSec: "sec-inf" },
  { name: "モーラステープ", gen: "ケトプロフェン", cat: "12. 整形外科 / 湿布", char: "整形外科の主役湿布！「貼付中および剥がした後4週間は日光遮断（光線過敏症厳禁！）」", desc: "強力な消炎鎮痛。紫外線暴露による光線過敏症（重篤な水疱・色素沈着）を防ぐため剥がした後も約1ヶ月は遮光するよう厳重指導。", gId: "c12", cSec: "sec-extra" },
  { name: "ジクトルテープ", gen: "ジクロフェナクNa", cat: "12. 整形外科 / 全身型湿布", char: "貼るだけで全身へ移行する全身吸収型NSAIDs！内服NSAIDsとの併用厳禁", desc: "変形性関節症やがん性疼痛に1日1回貼付。経口NSAIDsと同様に胃潰瘍・腎障害リスクがあるため内服NSAIDs併用不可。", gId: "c12", cSec: "sec-extra" },
  { name: "イベニティ", gen: "ロモソズマブ", cat: "新薬 / 骨粗鬆症", char: "骨形成促進＋骨吸収抑制のデュアルアクション！月1回2本皮下注（12ヶ月限定）", desc: "抗スクレロスチン抗体。過去1年以内の心筋梗塞・脳卒中歴は禁忌！12ヶ月終了後は骨量維持のため必ずプラリアまたはBPへ移行（シーケンシャルセラピー）。", gId: "tab-newdrugs", cSec: "sec-ckd" },
  { name: "オスタバロ", gen: "アバロパラチド酢酸塩", cat: "新薬 / 骨粗鬆症", char: "骨吸収を刺激せず骨形成を選択的促進！新規PTH1受容体作動薬（1日1回・18ヶ月上限）", desc: "高骨折リスク骨粗鬆症の切り札。初期の起立性低血圧・めまいに注意。通算18ヶ月まで。終了後はプラリアまたはBPへバトンタッチ。", gId: "tab-newdrugs", cSec: "sec-ckd" },
  { name: "フォルテオ / テリボン", gen: "テリパラチド / テリパラチド酢酸塩", cat: "10. 骨粗鬆症（PTH）", char: "副甲状腺ホルモン間歇投与で骨梁を再構築！重症骨折例の切り札（通算24ヶ月上限）", desc: "骨芽細胞を刺激し骨形成を促進。投与初期の立ちくらみ・めまい・嘔気（投与後30分安静）。通算24ヶ月終了後はBPまたはプラリアへ移行。", gId: "c10", cSec: "sec-ckd" },
  { name: "ビビアント / エビスタ", gen: "バゼドキシフェン / ラロキシフェン", cat: "10. 骨粗鬆症（SERM）", char: "閉経後早期の椎体骨折を予防する選択的エストロゲン調節薬（深部静脈血栓症VTE禁忌！）", desc: "骨のエストロゲン受容体にアゴニスト、乳腺・子宮にアンタゴニストとして作用。静脈血栓塞栓症（肺塞栓・深部静脈血栓）の既往は禁忌。長期臥床時休薬。", gId: "c10", cSec: "sec-ckd" },
  { name: "プラリア", gen: "デノスマブ", cat: "10. 骨粗鬆症", char: "半年に1回皮下注の強力骨粗鬆症薬（低Ca血症＆中断骨折に注意！）", desc: "骨へのカルシウム取り込みが凄まじいためデノタスチュアブル併用が必須。半年の期限を過ぎて中断するとリバウンドで多発骨折を起こす！", gId: "c10", cSec: "sec-ckd" },
  { name: "エディロール", gen: "エルデカルシトール", cat: "10. 骨粗鬆症", char: "最も使われる活性型ビタミンD3製剤（夏場の高Ca血症に厳戒！）", desc: "脱水になると血清カルシウムが急上昇し意識障害や急性腎障害を起こす。定期的な血清Ca値モニタリングが必要。", gId: "c10", cSec: "sec-ckd" },

  // 11. 消化器
  { name: "アミティーザ / リンゼス / グーフィス / モビコール", gen: "ルビプロストン / リナクロチド / エロビキシバット / PEG", cat: "11. 消化器（便秘）", char: "酸化Mgの次の一手！アミティーザは「食後（吐き気防止）」、リンゼス・グーフィスは「食前」！", desc: "高齢者の漫然酸化Mg（高Mg血症リスク）からの切り替え先。アミティーザは妊婦禁忌、リンゼスは腹痛を伴う便秘（IBS-C）に最強、モビコールは小児から腎不全まで万能。", gId: "c11", cSec: "sec-extra" },
  { name: "酸化マグネシウム (マグミット)", gen: "酸化マグネシウム", cat: "11. 消化器（便秘）", char: "高齢・腎不全の漫然投与は「高Mg血症」の危険！タケキャブ併用で効果が落ちる＆キレート形成王！", desc: "胃酸がないと塩化Mgに変身できず効果が落ちる。ニューキノロン、テトラサイクリン、チラーヂンS、ビスホスホネート等の吸収を阻害するため2時間空ける！", gId: "c11", cSec: "sec-extra" },
  { name: "リアルダ / ペンタサ / アサコール", gen: "メサラジン (5-ASA)", cat: "11. 消化器（IBD）", char: "潰瘍性大腸炎の主役だが、開始2週間の「発熱・下痢悪化（5-ASAアレルギー）」を見逃すな！", desc: "ペンタサは小腸から放出、アサコール・リアルダは大腸で放出される製剤設計の違いがある。", gId: "c11", cSec: "sec-extra" },

  // 12. 整形・疼痛・片頭痛
  { name: "タリージェ / リリカ", gen: "ミロガバリン / プレガバリン", cat: "12. 疼痛・整形", char: "神経の漏電（しびれ・坐骨神経痛）を止める主役！100%腎排泄＆初期のめまい・転倒に厳戒態勢！", desc: "必ず少量から開始し、eGFR（CCr）に応じた減量監査を行うこと。タリージェの方がα2δ-1選択性が高く現在の主流。", gId: "c12", cSec: "sec-extra" },
  { name: "トラムセット / ワントラム / ツートラム", gen: "トラマドール（＋アセトアミノフェン）", cat: "12. 疼痛・整形", char: "非麻薬の弱オピオイド！開始初期の「吐き気・便秘」対策と、トラムセットの「アセトアミノフェン重複」に注意！", desc: "トラムセットは1錠中にアセトアミノフェン325mgを含むため、風邪でカロナール等が追加されたら過量投与（肝障害）を防ぐため疑義照会必須！", gId: "c12", cSec: "sec-extra" },
  { name: "マクサルト / アマージ / レイボー", gen: "リザトリプタン / ナラトリプタン / ラスミジタン", cat: "12. 片頭痛", char: "マクサルトは即効性No.1（インデラル併用禁忌！）、アマージは持続型、レイボーは血管を縮めない新世代！", desc: "トリプタンは片頭痛が始まった初期に飲むのが鉄則。月10日以上の服用は「薬物乱用頭痛」を招くため予防薬（エムガルティ等）を検討。", gId: "c12", cSec: "sec-extra" },

  // 13. 内分泌・女性医療
  { name: "メルカゾール", gen: "チアマゾール", cat: "13. 甲状腺（バセドウ病）", char: "開始2ヶ月間の「急な発熱＋のどの痛み」は致死的な『無顆粒球症』のサイン！即受診！", desc: "バセドウ病の第一選択。無顆粒球症の初期症状は風邪とそっくりなため、絶対に市販の風邪薬で様子を見させないこと！", gId: "c13", cSec: "sec-extra" },
  { name: "チラーヂンS", gen: "レボチロキシン", cat: "13. 甲状腺（橋本病）", char: "鉄剤・酸化Mg・Ca製剤と一緒に飲むと吸収されなくなる！高齢者・心疾患は超少量から開始！", desc: "同時服用でキレートを形成するため服用時間をずらす。高齢者にいきなり通常量を出すと狭心症や心不全を誘発する。", gId: "c13", cSec: "sec-extra" },
  { name: "ルナベル / ヤーズ / ジェミーナ", gen: "LEP（低用量エストロゲン・プロゲスチン配合薬）", cat: "13. 女性医療", char: "月経困難症の救世主だが、ふくらはぎの痛み・胸痛・激しい頭痛（ACHES）は血栓症の緊急サイン！", desc: "喫煙者（35歳以上1日15本以上）や前兆のある片頭痛患者には血栓リスクのため禁忌！手術前4週間は休薬が必要。", gId: "c13", cSec: "sec-extra" },

  // 14. 眼科・耳鼻科
  { name: "キサラタン / タプロス / エイベリス", gen: "ラタノプロスト / タフルプロスト / オミデネパグ", cat: "14. 眼科（緑内障）", char: "PG関連薬は色素沈着・まつ毛伸長を防ぐため「入浴前点眼or拭き取り」！エイベリスは眼内レンズ禁忌！", desc: "緑内障の第一選択。エイベリスは色素沈着を起こさないが、白内障手術後（眼内レンズ挿入眼）には黄斑浮腫を起こすため禁忌！", gId: "c14", cSec: "sec-extra" },
  { name: "チモプトールXE / コソプト / ミケルナ", gen: "チモロール等のβ遮断薬点眼・配合点眼", cat: "14. 眼科（緑内障）", char: "目薬なのに全身に吸収されて「喘息発作・徐脈・心不全」を起こす！ゲル化剤（XE）は必ず最後に差す！", desc: "点眼後は目頭（涙嚢部）を1〜5分押さえて全身吸収を防ぐ。喘息既往の聞き取りは内服薬と同じくらい重要！", gId: "c14", cSec: "sec-extra" },

  // 15. 肝胆膵
  { name: "モニラック / ピアーレ / リフキシマ / リーバクト", gen: "ラクツロース / リファキシミン / BCAA", cat: "15. 肝胆膵（肝硬変）", char: "肝硬変の「アンモニア解毒カルテット」！ラクツロースは便秘薬ではなく「1日2〜3回軟便を出して脳を守る薬」！", desc: "手の震え（羽ばたき振戦）や昼夜逆転は肝性脳症のサイン。リーバクトは水に溶けないためオブラートやゼリー活用を指導。", gId: "c15", cSec: "sec-extra" },

// 16. 新薬トレンド図鑑・最新臨床薬
  { name: "マンジャロ (ゼップバウンド)", gen: "チルゼパチド", cat: "新薬 / 糖尿病・肥満", char: "GIP/GLP-1デュアル作動薬！圧倒的な血糖低下と体重減少をもたらす王者", desc: "必ず週1回2.5mgを4週間続けてから5mgへ増量。高齢者のサルコペニア・フレイル、急激な体重減少に伴う胆石症・急性胆嚢炎に厳戒注意。アテオス型デバイス。", gId: "tab-newdrugs", cSec: "t-meta" },
  { name: "ウゴービ", gen: "セマグルチド (高用量)", cat: "新薬 / 肥満症", char: "肥満症の保険適用薬！GLP-1受容体作動薬で中枢性食欲抑制", desc: "0.24mgから開始し4週間ごとに段階的に2.4mgまで増量。悪心・嘔吐等の消化器症状、脱水、急性膵炎に注意。保険適用の要件（BMI・合併症）確認必須。", gId: "tab-newdrugs", cSec: "t-meta" },
  { name: "ツイミーグ", gen: "イメグリミン", cat: "新薬 / 糖尿病", char: "ミトコンドリアを元気にしインスリン分泌と抵抗性を両面改善", desc: "メトホルミンと構造が似ているが乳酸アシドーシスの頻度は低い。消化器症状（悪心・下痢）に注意。eGFR45未満は慎重投与または減量。", gId: "tab-newdrugs", cSec: "t-meta" },
  { name: "ケレンディア", gen: "フィネレノン", cat: "新薬 / CKD・心保護", char: "2型糖尿病を合併するCKDの心腎を守る非ステロイド型選択的MRA", desc: "アルブミン尿を有意に減少させ末期腎不全・心血管死リスクを低下。血清カリウム上昇リスク（K≧5.5で中断）、eGFR25未満禁忌。CYP3A4阻害薬併用に注意。", gId: "tab-newdrugs", cSec: "t-meta" },
  { name: "ボルズィ", gen: "ボルノレキサント水和物", cat: "新薬 / 不眠症", char: "半減期約2時間！オレキシン拮抗薬最短のキレ味で翌朝の持ち越し眠気を完全撃退", desc: "最高血中濃度到達時間（Tmax）約0.5h、半減期約2.1hの超短時間型デュアルオレキシン受容体拮抗薬。入眠困難に切れ味よく効き朝には完全に抜ける。イトラコナゾール、クラリスロマイシン、ゾコーバ等の強力なCYP3A4阻害薬とは併用禁忌。中等度阻害薬併用時は2.5mgへ減量。", gId: "tab-newdrugs", cSec: "t-neuro" },
  { name: "クービビック", gen: "ダリドレキサント", cat: "新薬 / 不眠症", char: "翌朝への持ち越し・ふらつきが最も少ない新世代デュアルオレキシン受容体拮抗薬", desc: "覚醒物質オレキシンの働きをブロック。CYP3A4強力阻害薬と併用禁忌。中等度阻害薬では25mg減量。悪夢・金縛り（睡眠麻痺）の初期説明が必要。", gId: "tab-newdrugs", cSec: "t-neuro" },
  { name: "エムガルティ / アジョビ / アイモビーグ", gen: "ガルカネズマブ / フレマネズマブ / エレヌマブ", cat: "新薬 / 片頭痛予防", char: "CGRPまたは受容体をブロックする月1回（3ヶ月に1回）片頭痛予防抗体", desc: "群発頭痛・慢性片頭痛の発作頻度を劇的に減少。冷蔵保存（室温に戻してから皮下注）。注射部位反応（発赤・硬結）や便秘に注意。", gId: "tab-newdrugs", cSec: "t-neuro" },
  { name: "レイボー", gen: "ラスミジタン", cat: "新薬 / 片頭痛急性期", char: "血管を収縮させない5-HT1F作動薬！虚血性心疾患でも使える急性期薬", desc: "トリプタン系と異なり血管収縮作用がないため心血管系合併症でも投与可能。中枢性副作用（めまい・傾眠）が強いため服用後運転は終日禁止。", gId: "tab-newdrugs", cSec: "t-neuro" },
  { name: "デュピクセント", gen: "デュピルマブ", cat: "新薬 / アトピー・喘息", char: "IL-4/13を叩き皮膚炎・喘息・鼻茸を劇的に改善する抗体バイオ製剤", desc: "アトピー性皮膚炎の痒み・紅斑を劇的に鎮火。結膜炎（目のかゆみ・充血）の副作用、初回2本・次回から2週に1回自己注射。冷蔵保存。", gId: "tab-newdrugs", cSec: "t-derm" },
  { name: "コレクチム / モイゼルト", gen: "デルゴシチニブ / ジファミラスト", cat: "新薬 / アトピー外用", char: "ステロイドのような皮膚菲薄化・毛細血管拡張を起こさない新世代外用薬", desc: "コレクチムは外用JAK阻害薬、モイゼルトはPDE4阻害薬。小児から使え、顔面や首など皮膚の薄い部位のアトピー長期コントロールに最適。", gId: "tab-newdrugs", cSec: "t-derm" },
  { name: "パキロビッドパック", gen: "ニルマトレルビル・リトナビル", cat: "新薬 / COVID-19", char: "重症化リスクの高いコロナ患者を救うが、併用禁忌が数十種におよぶ地雷薬", desc: "リトナビルがCYP3A4を超強力阻害。スタチン・DOAC・睡眠薬・降圧薬など多くの日常薬と併用禁忌！お薬手帳の全薬剤・サプリの徹底照合が必須。", gId: "tab-newdrugs", cSec: "t-other" },
  { name: "ゾコーバ", gen: "エンシトレルビル", cat: "新薬 / COVID-19", char: "軽症・中等症コロナの罹患期間を短縮する国産プロテアーゼ阻害薬", desc: "妊婦・妊娠可能性のある女性には催奇形性のため絶対禁忌！CYP3Aを阻害するため多くの併用禁忌あり。初日375mg（3錠）、2〜5日目125mg（1錠）。", gId: "tab-newdrugs", cSec: "t-other" },
  { name: "レルミナ", gen: "レルゴリクス", cat: "新薬 / 婦人科", char: "世界初の経口GnRHアンタゴニスト！子宮筋腫・内膜症の出血と痛みを止める", desc: "必ず「食前服用」（食後だと吸収率激減）。エストロゲンを低下させるため更年期様症状（ほてり・発汗）や骨密度低下に注意（原則6ヶ月上限）。", gId: "tab-newdrugs", cSec: "t-other" },
  { name: "ボノサップ / ボノピオン", gen: "ボノプラザン・アモキシシリン・クラリスロマイシン等", cat: "新薬 / ピロリ除菌", char: "P-CAB＋抗菌薬2種のピロリ菌除菌パック製剤！7日間確実に飲み切る", desc: "ボノプラザンの強力な胃酸分泌抑制により除菌率90%以上。下痢・軟便・味覚異常の頻度が高いが、自己中断せず7日間飲み切るよう指導。", gId: "tab-newdrugs", cSec: "t-other" },

  // --- Core 17〜23 実戦調剤薬局領域薬剤 ---
  { name: "フェブリック", gen: "フェブキソスタット", cat: "17. 高尿酸血症・痛風", char: "腎機能低下でも使いやすい非プリン型XOR阻害薬（発作中の開始厳禁！）", desc: "尿酸生成を抑制。痛風発作中の新規開始・増量は発作を激化させるため絶対厳禁！少量（10mg）から開始。メルカプトプリン・アザニン（アザチオプリン）とは絶対併用禁忌！", gId: "c17", cSec: "sec-ckd" },
  { name: "ユリス", gen: "ドチヌラド", cat: "17. 高尿酸血症・痛風", char: "URAT1を選択的阻害し尿酸排泄を促進（尿路結石には禁忌！）", desc: "他の有機イオントランスポーターを邪魔せず選択的に尿酸を尿へ捨てる。尿路結石合併例には尿酸結石が増加するため禁忌。ウラリット等で尿アルカリ化を併用。", gId: "c17", cSec: "sec-ckd" },
  { name: "ウラリット配合錠", gen: "クエン酸カリウム・クエン酸ナトリウム", cat: "17. 高尿酸血症 / 結石予防", char: "酸性尿をアルカリ化して尿酸結石を防ぐ（pH 6.2〜6.9目標！）", desc: "痛風・高尿酸血症患者の酸性尿を是正。尿pHが7.0を超えるとリン酸カルシウム結石のリスクが生じるためアルカリにしすぎないよう試験紙で管理。", gId: "c17", cSec: "sec-ckd" },
  { name: "フェロミア / フェルム / インクレミン", gen: "クエン酸第一鉄Na / 溶性ピロリン酸第二鉄 / ピロリン酸第二鉄", cat: "19. 貧血（経口鉄剤）", char: "2価鉄の基準薬フェロミア vs 胃腸障害激減カプセル・フェルム！小児シロップ", desc: "フェロミアで胃もたれ・悪心時は徐放カプセルのフェルム（就寝前1回）へ変更提案。小児はインクレミンシロップ（歯の着色防止指導）。便の黒色化は正常。チラーヂンとキレート2時間空け。", gId: "c19", cSec: "sec-ckd" },
  { name: "モノファー / フェインジェクト", gen: "デルイソマルトース鉄 / カルボキシマルトース第二鉄", cat: "19. 貧血（新世代高用量静注鉄剤）", char: "通院1回で鉄欠乏を急速満タン！経口鉄剤不耐・産科出血の革命的静注鉄剤", desc: "高分子鉄錯体。1回最大500〜1000mgを急速投与可能。従来のフェジンのように連日通院せず1回で補充完結。投与後30分のショック観察と低リン血症に注意。", gId: "c19", cSec: "sec-ckd" },
  { name: "エナロイ / エバレン", gen: "エナロデュスタット / エバロデュスタット", cat: "19. 腎性貧血（HIF-PH阻害薬）", char: "透析・保存期CKDの腎性貧血を注射なしで治す新世代経口薬", desc: "低酸素誘導因子プロリン水酸化酵素を阻害し、内因性エリスロポエチン産生と鉄利用を同時促進。注射（ESA）に通えない在宅患者に福音。血栓塞栓症や血圧上昇に注意。", gId: "c19", cSec: "sec-ckd" },
  { name: "ボノサップパック / ボノピオンパック", gen: "タケキャブ・サワシリン・クラリス / フラジール", cat: "21. ピロリ菌除菌", char: "P-CAB配合の7日間除菌パック（二次除菌フラジールは絶対禁酒！）", desc: "胃酸分泌を完全に止めpH>6を維持してアモキシシリンの抗菌力を最大化。二次除菌（ボノピオン）はメトロニダゾールを含むため、アルコールを飲むとジスルフィラム様ショックを起こす！絶対禁酒！", gId: "c21", cSec: "sec-inf" },
  { name: "ウトロゲスタン / ルティナス", gen: "プロゲステロン", cat: "22. 不妊治療（生殖補助医療）", char: "胚移植後の黄体補充腟用製剤（絶対に口から飲むな！時間厳守！）", desc: "子宮内膜を着床・妊娠維持状態に保つ。カプセル剤だが「腟用坐薬」であり絶対に経口内服してはならない！投与間隔（8時間毎等）が乱れると内膜剥離・出血を招く。", gId: "c22", cSec: "sec-extra" },
  { name: "ゴナールエフ皮下注ペン", gen: "フォリトロピン アルファ", cat: "22. 不妊治療（rFSH製剤）", char: "自宅で卵胞を発育させる自己注射ペン（冷所保存・針廃棄徹底！）", desc: "複数の卵胞を発育させるリコンビナントFSH。使用前は冷蔵保存（凍結厳禁）。卵巣過剰刺激症候群（OHSS：下腹部痛・腹水・息切れ）に厳重警戒。使用済み針は薬局回収。", gId: "c22", cSec: "sec-extra" },
  { name: "ゲーベン軟膏", gen: "スルファジアジン銀", cat: "23. 褥瘡・創傷外用薬", char: "黒色期・黄色期の感染壊死組織を殺菌・軟化する銀含有軟膏", desc: "銀イオンによる強力殺菌と壊死組織の自己融解促進。浸出液が多い創や感染創に使用。銀・サルファ剤の吸収による白血球減少症（骨髄抑制）や疼痛に注意。", gId: "c23", cSec: "sec-imm" },
  { name: "ユーパスタコーワ軟膏", gen: "精製白糖・ポビドンヨード", cat: "23. 褥瘡・創傷外用薬", char: "黄色期のジュクジュク創から水を強力に吸い取る吸水・殺菌ペースト", desc: "白糖の高浸透圧で創部の過剰な浸出液・浮腫を脱水し肉芽形成を促進。ポビドンヨードで殺菌。乾いた創（肉芽形成期）に塗ると浸透圧で激痛・肉芽融解を起こすため禁忌！", gId: "c23", cSec: "sec-imm" },
  { name: "プロスタンディン軟膏", gen: "アルプロスタジル アルファデクス", cat: "23. 褥瘡・創傷外用薬", char: "赤色期の良性肉芽を盛り上げるPGE1血流促進軟膏", desc: "微小循環血流を促進し、毛細血管と新鮮肉芽の増殖を促す。油脂性基剤のため浸出液が少ない創に適する。ジュクジュク創に塗るとふやけて悪化するため注意。", gId: "c23", cSec: "sec-imm" },

  // --- Core 24 肺炎・呼吸器感染症マスター薬剤 ---
  { name: "オゼックス細粒小児用", gen: "トスフロキサシントシル酸塩水和物", cat: "24. 肺炎・呼吸器感染症（小児キノロン）", char: "小児耐性マイコプラズマ・PRSPの切り札（厳格体重換算！）", desc: "小児に適応のある数少ないニューキノロン系抗菌薬。クラリス等マクロライド耐性マイコプラズマ肺炎やPRSPに切り札として使用。関節軟骨障害の懸念から漫然連用を避け、適応菌種と1回6mg/kg 1日2回の用量を厳格遵守。", gId: "c24", cSec: "sec-inf" },
  { name: "ミノマイシン", gen: "ミノサイクリン塩酸塩", cat: "24. 肺炎・呼吸器 / 34. 尋常性ざ瘡（ニキビ）", char: "耐性マイコプラズマ第二選択 ＆ ニキビ急性期推奨度A（めまい注意・8歳未満歯牙着色禁忌）", desc: "テトラサイクリン系。マクロライド耐性マイコプラズマ肺炎や赤ニキビ急性期（抗菌＋抗炎症作用）に極めて有効。若年女性等で前庭障害（めまい・ふらつき：10〜30%）が出やすいため、不耐時はビブラマイシンへ変更。ニキビは原則3ヶ月以内に中止。8歳未満歯牙着色禁忌・妊婦禁忌。", gId: "c24", cSec: "sec-imm" },
  { name: "ジスロマック", gen: "アジスロマイシン水和物", cat: "24. 肺炎・呼吸器感染症 / 感染症", char: "3日間服用で7日間抗菌力が持続する高組織移行性マクロライド", desc: "白血球やマクロファージ内に高濃度移行し感染局所に留まる。マイコプラズマ肺炎やクラミドフィラ肺炎、百日咳に頻用。食事の影響を受けにくい。近年マクロライド耐性菌が増加している点に留意。", gId: "c24", cSec: "sec-inf" },
  { name: "ジェニナック / ラスビック", gen: "ガレノキサシン / ラスクフロキサシン", cat: "24. 肺炎・呼吸器感染症（キノロン）", char: "肺炎球菌と非定型菌を一網打尽にする呼吸器特化型キノロン", desc: "市中肺炎の主要原因菌である肺炎球菌からマイコプラズマ・レジオネラ・クラミドフィラまで1剤で強力にカバー。1日1回投与でアドヒアランス良好。金属イオン（鉄・Mg・Ca）とのキレート相互作用に注意。", gId: "c24", cSec: "sec-inf" },
  { name: "ユナシン / ユナシンS", gen: "アンピシリンナトリウム・スルバクタムナトリウム", cat: "24. 誤嚥性肺炎 / 感染症", char: "嫌気性菌を叩く誤嚥性肺炎の絶対的ゴールドスタンダード（注射）", desc: "ペニシリン系アンピシリンにβラクタマーゼ阻害薬スルバクタムを配合。口腔内嫌気性菌（ペプトストレプトコッカス等）とグラム陽性・陰性菌を広くカバーし、高齢者・在宅誤嚥性肺炎の第一選択。", gId: "c24", cSec: "sec-inf" },

  // --- Core 25 気管支喘息・咳喘息・COPD薬剤 ---
  { name: "レルベア エリプタ", gen: "フルチカゾンフランカルボン酸エステル / ビランテロールトリフェニル酢酸塩", cat: "25. 気管支喘息・COPD（ICS/LABA配合剤）", char: "1日1回1吸入で24時間持続！カバー開閉1アクションのアドヒアランス最強製剤", desc: "ICS/LABA配合剤。カバーをカチッと開けるだけで充填完了。テリルジーと同一デバイス（エリプタ）のため将来のステップアップも器具変更なし。吸入後の2段階うがい徹底。", gId: "c25", cSec: "sec-imm" },
  { name: "シムビコート タービュヘイラー", gen: "ブデソニド / ホルモテロールフマル酸塩水和物", cat: "25. 気管支喘息（SMART療法）", char: "定期吸入も発作時頓用もこれ1本！画期的SMART療法", desc: "速効性LABA（ホルモテロール）とICSの配合剤。維持療法だけでなく発作時にも追加吸入（1日最大8吸入）可能。吸入後は必ずブクブク＋ガラガラうがい。", gId: "c25", cSec: "sec-imm" },
  { name: "テリルジー エリプタ", gen: "フルチカゾンフランカルボン酸 / ビランテロール / ウメクリジニウム", cat: "25. 喘息・COPD（3剤トリプル）", char: "処方実績No.1！喘息（100/200）＆ COPD（100のみ）両適応の1日1回最強トリプル", desc: "ICS/LABA/LAMA 3剤配合。重症喘息やCOPDを1日1回1吸入で完全制圧。COPDは100エリプタのみ（200は過量）。抗コリン成分のため閉塞隅角緑内障・前立腺肥大の排尿障害は禁忌！", gId: "c25", cSec: "sec-imm" },
  { name: "ビレーズトリ エアロスフィア（ビレーズ）", gen: "ブデソニド / グリコピロニウム / ホルモテロール", cat: "25. COPD（3剤トリプル・pMDI）", char: "【COPDのみ適応（喘息不可！）】吸気力の落ちた重症肺気腫患者を救うpMDIスプレー", desc: "微粒子共懸濁エアゾール。息を吸い込む力が極度に低下した高齢COPD患者でも霧が気道奥へ届く。1日2回各2吸入。喘息病名単独では適応外（保険査定）。緑内障・前立腺肥大禁忌。", gId: "c25", cSec: "sec-imm" },
  { name: "エナジア ブリーズヘラー", gen: "モメタゾンフランカルボン酸 / インダカテロール / グリコピロニウム", cat: "25. 気管支喘息（3剤トリプル・五感確認）", char: "【気管支喘息のみ適応（COPD不可！）】カラカラ回転音と空カプセル目視で五感吸入確認", desc: "カプセル式DPI。1日1回1カプセル。「吸えた実感」が100%確認できる。COPD病名単独では適応外。カプセル内服厳禁。抗コリン成分のため緑内障・前立腺肥大禁忌。", gId: "c25", cSec: "sec-imm" },
  { name: "シングレア / キプレス", gen: "モンテルカストナトリウム", cat: "25. 喘息 / アレルギー", char: "夜間〜早朝の気道収縮を抑える経口LTRA（寝る前服用！）", desc: "ロイコトリエン受容体拮抗薬。小児から高齢者まで飲みやすい。モーニングサージ（早朝悪化）を防ぐため就寝前投与が合理的。アレルギー性鼻炎合併にも頻用。", gId: "c25", cSec: "sec-imm" },
  { name: "メプチンエアー / サルタノール", gen: "プロカテロール / サルブタモール", cat: "25. 急性発作治療薬（SABA）", char: "気管支発作時の即効レスキュー！月1本以上使い切りは重症化警告！", desc: "短時間作用性β2刺激薬。数分で気管支拡張。使いすぎ（1ヶ月1本以上）は気道炎症悪化と心臓負荷（頻脈・振戦・不整脈死リスク）のサイン。速やかにICS強化が必要。", gId: "c25", cSec: "sec-imm" },

  // --- 吸入デバイス指導 ＆ 点鼻薬特設 ---
  { name: "吸入デバイス指導（DPI vs pMDI / SMI）", gen: "エリプタ / タービュヘイラー / ブリーズヘラー / レスピマット", cat: "25. 呼吸器（吸入指導）", char: "粉末DPIは「強く速く」、霧状pMDIは「ゆっくり深く」！吸入後5秒息止め・2段階うがい", desc: "吸入効果不十分の8割は手技ミス。DPIは強く一気に吸い込み、pMDI/レスピマットはゆっくり深く吸う。吸入器への息吹き込み厳禁。声枯れ防止にブクブク＋ガラガラ両方のうがいを徹底。", gId: "c25", cSec: "sec-imm" },
  { name: "アラミスト点鼻液", gen: "フルチカゾンフランカルボン酸エステル", cat: "28. 点鼻薬（ステロイド）", char: "独自の横押し型デバイス！液だれが少なく1日1回で24時間効果持続", desc: "懸濁性点鼻薬。使用直前によく振る。鼻中隔を避け「目尻（外側）」に向けて噴霧するクロスハンド法で鼻出血を防止。強くスースー吸い込まず軽く自然呼吸でプッシュ。", gId: "c28", cSec: "sec-imm" },
  { name: "ナゾネックス点鼻液", gen: "モメタゾンフランカルボン酸エステル水和物", cat: "28. 点鼻薬（ステロイド）", char: "全身移行率0.1%未満で小児・妊婦でも安心の最高峰安全性！1日1回噴霧", desc: "局所選択性が極めて高く飲み込んでも肝臓でほぼ100%不活化。症状がなくても毎日継続して鼻粘膜の好酸球性炎症を鎮火。即効性の頓服ではないことを指導。", gId: "c28", cSec: "sec-imm" },
  { name: "エリザス点鼻粉末", gen: "デキサメタゾンシエノプロピオン酸エステル", cat: "28. 点鼻薬（ドライパウダー）", char: "唯一無二の粉末点鼻薬！液だれ・喉落ち・苦味ゼロ＆防腐剤フリー", desc: "液状スプレーの刺激やタラッと垂れてくる不快感を嫌う患者に最適。防腐剤無添加。強く吸い込みすぎず「軽く息を吸いながら」噴霧させるのが指導の急所。", gId: "c28", cSec: "sec-imm" },
  { name: "血管収縮性点鼻薬（市販ナザール等）", gen: "ナファゾリン / トラマゾリン / 硝酸テトラヒドロゾリン", cat: "28. 点鼻薬（α作動薬・薬剤性鼻炎）", char: "数分で鼻が通る驚異の即効性だが1〜2週間連用で「薬剤性肥厚性鼻炎」の地雷！", desc: "鼻粘膜血管を強制収縮させて鼻を通すが、連用すると受容体脱感作で薬が切れた際に激しい反跳性鼻閉（リバウンド）を招く。市販薬連用患者は直ちにステロイド点鼻へ移行支援。", gId: "c28", cSec: "sec-imm" },

  // --- 吸入薬 単剤 ＆ 経口NSAIDs単剤 特設 ---
  { name: "オルベスコ / パルミコート / フルタイド", gen: "シクレソニド / ブデソニド / フルチカゾン", cat: "25. 喘息（ICS単剤）", char: "プロドラッグで声枯れ激減のオルベスコ！乳幼児ネブライザーのパルミコート液！", desc: "オルベスコは肺内エステラーゼで活性化されるプロドラッグで嗄声・カンジダが極小。パルミコート吸入液は吸えない乳幼児喘息発作の救世主。フルタイドはエビデンス最多の基準薬。", gId: "c25", cSec: "sec-imm" },
  { name: "ホクナリンテープ", gen: "ツロブテロール", cat: "25. 喘息（気管支拡張貼付薬）", char: "吸えない小児・認知症の救世主！就寝前貼付で早朝モーニングサージを鉄壁ブロック", desc: "結晶レジボアシステムで24時間一定放出。吸入困難な乳幼児や認知症患者に最適。皮膚刺激・かぶれ予防のため毎日貼る場所を変える指導が必須。", gId: "c25", cSec: "sec-imm" },
  { name: "セレコックス", gen: "セレコキシブ", cat: "15. 整形外科（選択的COX-2阻害薬）", char: "胃潰瘍リスクを半減させた長期連用型NSAIDs！スルホンアミド禁忌＆心血管注意", desc: "胃粘膜保護のCOX-1を温存しCOX-2を選択的阻害。変形性関節症や腰痛の長期維持に第一選択。スルホンアミド過敏症は禁忌。心筋梗塞既往など虚血性心疾患には注意。", gId: "c15", cSec: "sec-extra" },
  { name: "ボルタレン", gen: "ジクロフェナクナトリウム", cat: "15. 整形外科（強力NSAIDs）", char: "消炎鎮痛パワー最強の重砲！尿路結石・痛風発作・激痛を一撃鎮圧（漫然投与厳禁）", desc: "COX阻害力が極めて強力。坐剤は最速吸収。胃障害・腎障害・心毒性も最強クラスのため漫然連用は絶対禁止。インフルエンザ脳症リスクのため小児解熱には禁忌。", gId: "c15", cSec: "sec-extra" },
  { name: "カロナール", gen: "アセトアミノフェン", cat: "15. 疼痛・発熱（安全解熱鎮痛薬）", char: "胃腸・腎臓・喘息・血小板への悪影響ゼロ！小児・妊婦・CKDの絶対王者（用量注意）", desc: "中枢性作用で胃粘膜障害や腎障害が皆無。成人の除痛には1回500〜1000mg（最大4000mg/日）の適切な用量確保が重要。少量（200mg）処方では効果不十分になりやすい。", gId: "c15", cSec: "sec-extra" },

  // --- アンチ・ドーピング ＆ スポーツ薬学 ---
  { name: "アンチ・ドーピング（うっかりドーピング防止）", gen: "【安全処方】タイレノールA / アレグラFX / メジコンPro / ペラックT錠", cat: "スポーツ薬学（アンチ・ドーピング）", char: "市販風邪薬のエフェドリン・漢方の麻黄・南天のど飴のヒゲナミンは一発失格！", desc: "うっかりドーピングの9割は市販薬。総合感冒薬や鼻炎薬のエフェドリン、葛根湯等の麻黄、南天のど飴が地雷。単一成分OTCで防護。ステロイド点鼻や吸入は使用可。TUE申請支援。", gId: "tab-otc", cSec: "o-doping" },

  // --- 薬剤師業務 ＆ 調剤報酬加算 ---
  { name: "調剤報酬加算・薬歴記載（個別指導・返戻対策）", gen: "特定薬剤管理指導加算1・2 / 重複投薬防止 / 吸入指導 / かかりつけ / 在宅", cat: "保険薬局実務（調剤加算・個別指導）", char: "コピペ記載は一発返還！ハイリスク薬の確認副作用・疑義照会医師名・TR写し保存が必須", desc: "調剤報酬の算定要件と薬歴記載の必須ルール。「副作用なし」定型文は返還対象。ハイリスク薬の具体的確認項目、重複投薬・残薬調整の照会医師名・時間、吸入指導・TRの提供文書写し保存を徹底指導。", gId: "tab-followup", cSec: "f-kasan" },

  // --- Core 14 眼科・白内障・点眼マスター薬剤 ---
  { name: "カリーユニ点眼用", gen: "ピレノキシン", cat: "14. 眼科（白内障進行予防）", char: "水晶体タンパク質の変性を防ぎ白内障の進行を遅らせる懸濁点眼薬", desc: "キノイド説に基づく初期白内障治療薬。混濁した水晶体を透明に戻す効果はなく「進行予防」が目的。粒子が沈殿するためよく振ってから点眼。水溶性点眼薬の次に点眼する。", gId: "c14", cSec: "sec-extra" },
  { name: "ブロムフェナク点眼液 / ネバナック", gen: "ブロムフェナクNa / ネパフェナク", cat: "14. 眼科（白内障術後・NSAIDs）", char: "白内障術後の最重要薬！痛くなくても「術後黄斑浮腫（CME）」を防ぐ生命線！", desc: "非ステロイド性抗炎症点眼薬。手術の炎症刺激でプロスタグランジンが網膜黄斑部に波及して視力が落ちる「術後黄斑浮腫（CME）」を強力に予防。「痛くないから差さない」は失明リスク！指示期間を厳格完遂。", gId: "c14", cSec: "sec-extra" },
  { name: "クラビット点眼液 / トスフロ点眼液", gen: "レボフロキサシン / トスフロキサシン", cat: "14. 眼科（抗菌点眼）", char: "細菌性結膜炎・白内障術前術後感染予防の主力キノロン点眼", desc: "黄色い目やに、角膜炎、術後眼内炎予防。1回1滴・1日3〜4回。容器先端が目やまつ毛に触れると薬液が逆流汚染するため浮かせて点眼。耐性菌防止のため指示期間使い切る。", gId: "c14", cSec: "sec-extra" },
  { name: "ヒアレイン点眼液 / ジクアス", gen: "ヒアルロン酸Na / ジクアホソルNa", cat: "14. 眼科（ドライアイ・角膜保護）", char: "涙の量と質を補い角膜を守るドライアイ・高齢者目やにの第一選択", desc: "ヒアレインは水分保持、ジクアスは水分＋ムチン分泌促進。ソフトコンタクト装用時は防腐剤BAKの吸着毒性を防ぐため外して点眼するか、防腐剤フリー（ミニ点眼）を選択。", gId: "c14", cSec: "sec-extra" },

  // 17. 頻出漢方薬・重要生薬
  { name: "芍薬甘草湯 (ツムラ68)", gen: "シャクヤク・カンゾウ", cat: "漢方 / 疼痛・痙攣", char: "こむら返り・胆石発作の即効レスキュー！甘草最多配合で連用厳禁！", desc: "頓服で10〜15分で効く。甘草が1日量中6.0g（生薬中最多）含まれるため、定期連用すると『偽アルドステロン症（低K血症・高血圧・むくみ）』を必発する！", gId: "tab-special", cSec: "sec-extra" },
  { name: "五苓散 (ツムラ17)", gen: "タクシャ・チョレイ・ブクリョウ・ビャクジュツ・ケイヒ", cat: "漢方 / 水滞・浮腫・頭痛", char: "アクアポリン（水チャネル）を調節し「水滞」を捌く！低気圧頭痛・二日酔い・急性胃腸炎に", desc: "血管や組織の過剰な水分を利尿し、脱水部位には影響しないスマート利尿。甘草を含まないため連用しやすい。小児の胃腸炎・嘔吐下痢にも頻用。", gId: "tab-special", cSec: "sec-extra" },
  { name: "抑肝散 (ツムラ54)", gen: "ソウジュツ・ブクリョウ・センキュウ・チョウトウコウ・シャクヤク・トウキ・カンゾウ", cat: "漢方 / 精神・不穏", char: "認知症のBPSD（暴言・徘徊・イライラ）・小児夜泣きの興奮を鎮める", desc: "釣藤鈎（チョウトウコウ）がグルタミン酸神経を抑えセロトニン神経を賦活。高齢者の睡眠薬・抗精神病薬の減量に寄与。甘草1.5g含有。", gId: "tab-special", cSec: "sec-psy" },
  { name: "防風通聖散 (ツムラ62)", gen: "18種類生薬配合（麻黄・甘草・大黄など）", cat: "漢方 / 代謝・便秘", char: "お腹の脂肪・便秘を落とす市販でも超人気の漢方！麻黄・甘草・大黄の三重奏に注意", desc: "麻黄（交感神経刺激・血圧上昇・動悸）、大黄（下痢・子宮収縮・妊婦注意）、甘草（偽アルドステロン症）を含むため、虚弱者・妊婦・心疾患には注意。", gId: "tab-special", cSec: "sec-ckd" },
  { name: "半夏厚朴湯 (ツムラ16)", gen: "ハンゲ・ブクリョウ・コウボク・ソヨウ・ショウキョウ", cat: "漢方 / 精神・咽喉", char: "喉に何かが引っかかっている感じ（梅核気）・不安神経症を和らげる「気の巡り」の薬", desc: "胃食道逆流症の喉違和感やパニック障害、咳にも使われる。甘草・麻黄を含まないため高齢者にも極めて安全。", gId: "tab-special", cSec: "sec-psy" },
  { name: "小青竜湯 (ツムラ19)", gen: "マオウ・カンゾウ・サイシン・カンキョウなど", cat: "漢方 / アレルギー・鼻炎", char: "サラサラした水鼻・くしゃみ・花粉症を速攻で止める！麻黄の動悸と高齢前立腺肥大に注意", desc: "麻黄・甘草・細辛配合。体を温めて水毒を乾かす。麻黄のエフェドリン作用による血圧上昇・頻脈・排尿障害（前立腺肥大）に注意。", gId: "tab-special", cSec: "sec-imm" },
  { name: "葛根湯 (ツムラ1)", gen: "カッコン・マオウ・カンゾウ・ショウキョウ・ケイヒ・シャクヤク・タイソウ", cat: "漢方 / 感冒・肩こり", char: "風邪の引き始め（悪寒・首筋のこわばり・汗が出ていない時）に体を温めて発汗させる", desc: "汗をすでにダラダラかいている時や胃腸虚弱者には不適。麻黄・甘草を含む。温かいお湯で服用するのが鉄則。", gId: "tab-special", cSec: "sec-inf" },

  // 18. 小児・在宅・救急臨床薬
  { name: "ダイアップ坐薬", gen: "ジアゼパム", cat: "小児 / 痙攣予防", char: "熱性けいれん予防坐薬！37.5℃以上の発熱時に1回目、8時間後に2回目を使用", desc: "脂溶性基剤（ウテップサポ）。アセトアミノフェン坐薬（水溶性基剤アンヒバ等）と併用時は、必ずダイアップを先に入れ、最低30分以上あけて解熱坐薬を入れる！", gId: "tab-special", cSec: "sec-psy" },
  { name: "アンヒバ / アルピニー坐薬", gen: "アセトアミノフェン", cat: "小児 / 解熱鎮痛", char: "小児の発熱・痛みの第一選択坐薬（体重換算10〜15mg/kg）", desc: "水溶性基剤（Witepsolなど）。直腸粘膜から速やかに吸収される。ダイアップ等の油性坐薬と一緒に挿入すると吸収が大幅に遅れるため時間差必須。", gId: "tab-special", cSec: "sec-extra" },

  // 19. 皮膚科・アレルギー外用薬（Core 16）
  { name: "リンデロン-V / リンデロン-VG", gen: "ベタメタゾン吉草酸エステル / ゲンタマイシン硫酸塩配合", cat: "16. 皮膚科（ストロング）", char: "実臨床で処方頻度No.1の標準ステロイド（Ⅲ群）！VGの漫然連用は耐性菌に注意", desc: "成人の体幹（軽〜中等症）や小児の体幹（中等〜重症）の主力。VGは二次感染を伴う湿疹に有効だが、感染治癒後はMRSA等の耐性菌予防のため速やかにV単剤へ切り替える。", gId: "c16", cSec: "sec-imm" },
  { name: "リドメックスコーワ", gen: "プレドニゾロン吉草酸エステル酢酸エステル（PVA）", cat: "16. 皮膚科（ミディアム・アンテドラッグ）", char: "局所で強く効いて血中で速やかに低活性化する安全設計のアンテドラッグ（Ⅳ群）", desc: "患部の皮膚表面では中等度の強い抗炎症作用を発揮し、吸収されて血管に入るとエステラーゼで速やかに分解。全身副作用が極めて少なく乳幼児や広範囲塗布に最適。", gId: "c16", cSec: "sec-imm" },
  { name: "ダイアコート / ジフラール", gen: "ジフロラゾン酢酸エステル", cat: "16. 皮膚科（ストロンゲスト）", char: "ステロイド外用薬の頂点（Ⅰ群）！手掌・足底の重症角化性皮膚疾患に", desc: "デルモベートと並ぶ最強群。角質の極めて厚い手のひら・足の裏、苔癬化病変に短期集中で使用。顔面・陰部・小児には原則使用しない。", gId: "c16", cSec: "sec-imm" },
  { name: "プレドニゾロン軟膏 / オイラックスH", gen: "プレドニゾロン / ヒドロコルチゾン＋クロタミトン", cat: "16. 皮膚科（ウィーク）", char: "最も作用がマイルドで安全重視のステロイド（Ⅴ群）！乳幼児デリケート部位に", desc: "作用が最も弱く安全性が高い。成人の苔癬化には力不足だが、乳幼児の顔面・陰部・おむつかぶれ軽症や眼瞼周囲の軽度炎症に限定して用いる。", gId: "c16", cSec: "sec-imm" },

  { name: "アンテベート / フルメタ", gen: "ベタメタゾン酪酸エステルプロピオン酸エステル / モメタゾン", cat: "16. 皮膚科（ベリーストロング）", char: "体幹・手足の強い皮膚炎を一気に消火する主力ステロイド（Ⅱ群）", desc: "体幹や四肢の急性湿疹・アトピーに第一選択。ツルツルになるまでしっかり適量（FTU）を塗布。漫然と顔面に使用すると酒さ様皮膚炎を起こすため注意。", gId: "c16", cSec: "sec-imm" },
  { name: "デルモベート", gen: "クロベタゾールプロピオン酸エステル", cat: "16. 皮膚科（ストロンゲスト）", char: "ステロイド外用薬の頂点（Ⅰ群）！手掌・足底の難治性苔癬化病変に", desc: "皮膚の厚い手のひら・足の裏や、苔癬化した頑固な皮疹に使用。吸収率が極めて高いため顔面・陰部・小児には原則使用しない。", gId: "c16", cSec: "sec-imm" },
  { name: "ロコイド / キンダベート", gen: "ヒドロコルチゾン酪酸エステル / クロベタゾン酪酸エステル", cat: "16. 皮膚科（ミディアム）", char: "顔面・首・陰部・小児にも安心して使えるマイルドステロイド（Ⅳ群）", desc: "皮膚の薄い部位のアトピーや乳幼児湿疹の定番。ベリーストロング等で炎症を抑えた後のステップダウン先としても頻用。", gId: "c16", cSec: "sec-imm" },
  { name: "プロトピック軟膏", gen: "タクロリムス水和物", cat: "16. 皮膚科（外用免疫抑制薬）", char: "ステロイドのような皮膚萎縮・毛細血管拡張を起こさないアトピー顔面維持薬", desc: "塗り始め数日間の「灼熱感・ほてり・ピリピリ感」は必発！事前に伝えておかないと患者が驚いて中止するため事前予告が鉄則。潰瘍面・小児用量（0.03%）注意。", gId: "c16", cSec: "sec-imm" },
  { name: "ヒルドイド (ソフト軟膏/ローション/フォーム)", gen: "ヘパリン類似物質", cat: "16. 皮膚科（保湿・血行促進）", char: "皮膚バリアの土台を作る保湿王！ステロイドより先に全身に塗るのが現場流", desc: "水分保持作用と血行促進作用を持つ。抗がん薬の手足症候群予防にも必須。出血性血液疾患（血友病、血小板減少等）には禁忌。", gId: "c16", cSec: "sec-imm" }
,
  { name: "エレンタール / ラコール / エンシュア", gen: "経腸栄養剤（成分栄養 / 消化態 / 半消化態）", cat: "在宅・栄養", char: "経口・経管で栄養を補給する生命線！下痢対策の投与速度とフレーバー活用がカギ", desc: "エレンタールは窒素源がアミノ酸で無脂肪（クローン病等）。エンシュア・ラコールはタンパク質含有。急激な注入は浸透圧性下痢を起こすため1時間以上かけて滴下。", gId: "tab-special", cSec: "sec-ckd" },

  // 妊娠・授乳期マスター（Special 06 追加）
  { name: "アルドメット", gen: "メチルドパ水和物", cat: "妊娠・高血圧（第一選択）", char: "妊娠高血圧症候群の世界的ゴールドスタンダード！胎児奇形・発育不全リスクなし", desc: "中枢性α2刺激薬。長年の疫学データが豊富で妊娠全期間で安全に使用可能。妊娠判明した高血圧女性の切り替え第一選択。起立性低血圧や眠気、肝機能に注意。", gId: "tab-special", cSec: "sec-pregnancy" },
  // 要指導医薬品（OTC 04 追加）
  { name: "アライ", gen: "オルリスタット", cat: "要指導医薬品（肥満改善薬）", char: "国内初の肥満改善薬！食事の脂肪の30%を便に排出！【生活習慣記録必須】", desc: "膵リパーゼ阻害薬。腹囲（男85cm、女90cm以上）かつ購入前3ヶ月の生活習慣改善記録の提示が必須。油漏れ（おならと一緒に油が出る）対策におむつ・ナプキンを指導。ビタミン剤は2時間あけて服用。", gId: "tab-otc", cSec: "o-guidance" },
  // 第1類医薬品（OTC 05 追加）
  { name: "ロキソニンS / プレミアム / ファイン", gen: "ロキソプロフェンナトリウム水和物", cat: "第1類医薬品（解熱鎮痛）", char: "NSAIDs市販薬の絶対王者！アスピリン喘息・妊娠後期28週以降は完全禁忌", desc: "プロドラッグ型NSAIDs。頭痛特化のプレミアム（眠気成分あり）、生理痛特化のプレミアムファイン（眠気なし）。アスピリン喘息・妊娠28週以降は禁忌。4時間以上あけて服用。", gId: "tab-otc", cSec: "o-first" },
  { name: "ガスター10", gen: "ファモチジン", cat: "第1類医薬品（H2ブロッカー）", char: "過剰な胃酸分泌を元から断つ！【連続服用は2週間まで！治らなければ受診】", desc: "H2ブロッカー。胃痛・胸やけに速効。連続服用は2週間まで（治らない胃痛は胃がん・潰瘍疑いで受診勧奨）。80歳以上高齢者（せん妄）、15歳未満不可。", gId: "tab-otc", cSec: "o-first" },
  { name: "リアップX5プラスネオ", gen: "ミノキシジル", cat: "第1類医薬品（発毛剤）", char: "国内唯一の発毛成分5%配合！高血圧・心疾患注意！女性には使用不可", desc: "男性壮年性脱毛症（AGA）治療薬。血管拡張作用があるため高血圧・低血圧・心血管疾患に注意。女性への5%使用は多毛症リスク等で禁忌（女性用は1%リジェンヌ）。最低4ヶ月連用。", gId: "tab-otc", cSec: "o-first" },
  { name: "トランシーノII", gen: "トラネキサム酸 / L-システイン等", cat: "第1類医薬品（肝斑改善薬）", char: "頬の左右対称のシミ（肝斑）に唯一効く！血栓症注意！【2ヶ月で必ず休薬】", desc: "トラネキサム酸750mg/日配合。メラニン産生を阻害。抗プラスミン作用による血栓リスクがあるため脳梗塞既往等は不可。最大2ヶ月服用後、必ず2ヶ月以上休薬する。", gId: "tab-otc", cSec: "o-first" },


  { name: "トランデート", gen: "ラベタロール塩酸塩", cat: "妊娠・高血圧（第一選択）", char: "妊娠高血圧症候群の第一選択！血管抵抗を下げ子宮胎盤血流を維持するαβ遮断薬", desc: "α1およびβ受容体を遮断。胎児への安全性が確立されており、メチルドパと並ぶ妊娠高血圧の二大標準薬。喘息患者には気管支攣縮リスクのため禁忌。", gId: "tab-special", cSec: "sec-pregnancy" },
  { name: "小半夏加茯苓湯", gen: "ショウハンゲカブクリョウトウ（ツムラ11番）", cat: "妊娠・つわり（漢方第一選択）", char: "つわり（妊娠悪阻）の神処方！生姜・半夏・茯苓が胃逆流と水分代謝を改善", desc: "妊娠初期の激しい吐き気・つわりに第一選択。生姜と半夏が中枢性制吐・胃運動正常化、茯苓が水毒を排泄。ビタミンB6併用で劇的に改善。冷水でゆっくり服用。", gId: "tab-special", cSec: "sec-pregnancy" },


  // 6. 精神神経疾患・精神科薬学マスター（Core 06 追加）
  { name: "ジプレキサ", gen: "オランザピン", cat: "06. 精神神経（MARTA）", char: "多元受容体に作用し不穏・焦燥・双極性を深く鎮静！糖尿病患者には原則禁忌", desc: "D2/5-HT/H1等に作用。鎮静力と気分安定化に優れるが食欲亢進・体重増加必発。【糖尿病に原則禁忌】。定期的な血糖・HbA1c測定が法的に義務付けられている。", gId: "c6", cSec: "sec-psy" },
  { name: "セロクエル", gen: "クエチアピンフマル酸塩", cat: "06. 精神神経（MARTA）", char: "鎮静・催眠作用が強くEPSが極めて少ない！糖尿病患者には原則禁忌", desc: "半減期が短く眠気・鎮静が強い。パーキンソン病患者の精神症状にも使いやすい。オランザピン同様【糖尿病患者に原則禁忌】。急激な高血糖昏睡に厳重注意。", gId: "c6", cSec: "sec-psy" },
  { name: "リスパダール / インヴェガ", gen: "リスペリドン / パリペリドン", cat: "06. 精神神経（SDA）", char: "幻覚・妄想を最速で鎮圧する切れ味No.1！EPSと高プロラクチン血症に注意", desc: "D2と5-HT2Aを高親和性遮断。陽性症状の消火力が高い。用量依存的な錐体外路症状（手の震え）や高プロラクチン血症（無月経・乳汁分泌・女性化乳房）を定期監査。", gId: "c6", cSec: "sec-psy" },
  { name: "エビリファイ / レキサルティ", gen: "アリピプラゾール / ブレクスピプラゾール", cat: "06. 精神神経（DSS）", char: "ドパミンを正常化し過鎮静・体重増加ゼロ！うつ病増強（1〜3mg）でも大活躍", desc: "D2部分作動薬。頭が冴えて社会復帰を支援。うつ病増強療法（Augmentation）として1〜3mg少量付加が頻用。初期のアカシジア（足のムズムズ）を見逃さない。", gId: "c6", cSec: "sec-psy" },
  { name: "ラツーダ", gen: "ルラシドン塩酸塩", cat: "06. 精神神経（新世代SDA系）", char: "双極性うつ病の第一選択！体重増加がなく代謝に優しい！【食後服用厳守】", desc: "双極性障害のうつ状態に適応。オランザピンと違い体重増加が極めて少ない。空腹時服用だと吸収が約半分に激減するため【必ず食後】に服用するよう徹底指導。", gId: "c6", cSec: "sec-psy" },
  { name: "リーマス", gen: "炭酸リチウム", cat: "06. 精神神経（気分安定薬）", char: "双極性躁病・維持療法の絶対王者！治療域狭小（TDM必須）・NSAIDs併用禁忌", desc: "自殺予防効果が証明された唯一の薬。有効域（0.4〜1.2 mEq/L）が狭い。ロキソニン等のNSAIDsや降圧薬併用で腎排泄低下し【リチウム中毒（振戦・昏睡）】を招く。", gId: "c6", cSec: "sec-psy" },
  { name: "ラミクタール", gen: "ラモトリギン", cat: "06. 精神神経（気分安定薬）", char: "双極性うつ病の再発予防に最強！重篤皮疹（SJS）防止の隔週倍増ルール厳守", desc: "うつ病相の再発を強力に食い止める。初期投与量の厳守（隔週倍増）が法的に義務。バルプロ酸併用時は代謝阻害されるため半量開始。発疹・発熱時は直ちに中止受診。", gId: "c6", cSec: "sec-psy" },
  { name: "コンサータ", gen: "メチルフェニデート塩酸塩徐放錠", cat: "06. 精神神経（中枢刺激薬）", char: "ADHDの中核薬！即効性・効果絶大！【適正流通管理システム・登録制】", desc: "DAT/NET阻害でドパミン急増。朝1回で約12時間集中力持続。登録医・登録薬局・患者カードの全照合が必須。処方上限30日。朝食直後服用で食欲減退・不眠を防止。", gId: "c6", cSec: "sec-psy" },
  { name: "ストラテラ", gen: "アトモキセチン塩酸塩", cat: "06. 精神神経（非中枢刺激薬）", char: "依存性ゼロ・登録制度不要のADHD薬！24時間穏やかに効果が持続", desc: "選択的NET阻害薬。効果発現まで2〜4週間かかるが24時間効果が持続し夕方の家庭生活も安定。悪心・頭痛に注意。登録不要で長期処方しやすい。", gId: "c6", cSec: "sec-psy" },
  { name: "インチュニブ", gen: "グアンファシン塩酸塩徐放錠", cat: "06. 精神神経（非中枢刺激薬）", char: "衝動性・多動性・イライラを劇的鎮静！【急な中止で反跳性高血圧注意】", desc: "シナプス後α2A受容体作動薬。前頭前皮質を強化し衝動性を抑える。眠気・低血圧に注意。急激な断薬でリバウンド高血圧を起こすため必ず徐々に漸減する。", gId: "c6", cSec: "sec-psy" },
  // 精神神経系・運動障害・錐体外路症状（EPS）特設
  { name: "アカシジア（静坐不能症）", gen: "【治療薬】プロプラノロール（インデラル）/ ビペリデン（アキネトン）", cat: "06. 精神神経（錐体外路症状・EPS）", char: "足がムズムズ・ソワソワして座っていられない！精神症状悪化と誤認した増量は自殺の危機", desc: "抗精神病薬（エビリファイ等）開始初期に発症。病状悪化と誤診して増量すると地獄の苦痛から自殺企図を招く最大地雷。第一選択はβ遮断薬（インデラル）。", gId: "c6", cSec: "sec-psy" },
  { name: "遅発性ジスキネジア（ジスバル錠）", gen: "バルベナジントシル酸塩（ジスバル）", cat: "06. 精神神経（錐体外路症状・EPS）", char: "口をもぐもぐ・舌をペロペロ出す不随意運動！抗コリン薬併用は激悪化の禁忌！", desc: "抗精神病薬長期投与でD2受容体が過敏化。抗コリン薬（アキネトン）を追加すると劇的悪化。VMAT2阻害薬（ジスバル錠）が標準治療。", gId: "c6", cSec: "sec-psy" },
  { name: "ウェアリング・オフ現象", gen: "【治療薬】オンジェンティス / コムタン / エクフィナ / エフピー", cat: "06. 精神神経（パーキンソン病運動合併症）", char: "次の服薬前に薬効が切れて体が固まる！COMT阻害薬やMAO-B阻害薬で底上げ", desc: "L-ドパ長期服用でドパミン貯蔵能が失われ血中濃度低下とともにOFF期突入。COMT阻害薬（オピカポン等）やMAO-B阻害薬の併用、服薬回数増加で改善。", gId: "c6", cSec: "sec-psy" },
  { name: "急性ジストニア", gen: "【治療薬】ビペリデン塩酸塩（アキネトン注射液・錠）", cat: "06. 精神神経（錐体外路症状・EPS）", char: "首のねじれ・眼球上転が突然起きる！アキネトン筋注・静注で劇的寛解", desc: "抗精神病薬投与開始初期にアセチルコリン神経が過剰暴走。抗コリン薬（アキネトン）投与により数分〜数十分で劇的に寛解。", gId: "c6", cSec: "sec-psy" },


  // 26. 慢性便秘症・消化管運動改善薬（Core 26）
  { name: "モビコール配合内服剤", gen: "マクロゴール4000 / 電解質配合（PEG製剤）", cat: "26. 慢性便秘症（浸透圧性下剤）", char: "体内に吸収されず水分子を抱え込んで届ける！腎不全・小児・高齢者第一選択のPEG製剤", desc: "ガイドライン最高推奨。高Mg血症リスクゼロで透析・CKD・2歳以上小児に極めて安全。1包あたり水約60mL（HDは120mL）に溶かして服用。塩味が苦手ならリンゴジュースやお茶等で割ってOK。", gId: "c26", cSec: "sec-extra" },
  { name: "ラグノスNF経口ゼリー", gen: "ラクツロース", cat: "26. 慢性便秘症（糖類浸透圧下剤）", char: "水なしでツルッと飲める分包ゼリー！水分制限患者に最適＆高Mg血症ゼロ", desc: "小腸で吸収されず大腸で有機酸に分解され浸透圧作用と蠕動を促進。水に溶かす手間がなく水分制限例に最適。初期の腹部膨満感・放屁に注意。肝性脳症改善。", gId: "c26", cSec: "sec-extra" },
  { name: "グーフィス", gen: "エロビキシバット水和物", cat: "26. 慢性便秘症（IBAT阻害薬）", char: "胆汁酸の再吸収を阻害して大腸運動と水分分泌を促す新世代薬！朝食前服用", desc: "回腸のIBATを阻害し大腸へ胆汁酸を届ける。食事刺激による胆汁酸分泌を利用するため【必ず朝食前】に服用。食後だと効果激減。刺激性下剤からの離脱に有効。LDL低下作用。", gId: "c26", cSec: "sec-extra" },
  { name: "リンゼス", gen: "リナクロチド", cat: "26. 慢性便秘症・IBS（GC-C作動薬）", char: "腸液分泌促進＋大腸痛覚神経を抑制して腹痛も改善！食前服用厳守", desc: "GC-C受容体を活性化し腸液を分泌。腹痛・腹部膨満感を抑える作用があり過敏性腸症候群（IBS）便秘型に第一選択。【必ず食前】に服用。食後だと激しい下痢を起こす。", gId: "c26", cSec: "sec-extra" },
  { name: "アミティーザ", gen: "ルビプロストン", cat: "26. 慢性便秘症（ClC-2開口薬）", char: "小腸から水分を分泌させて便を押し出す上皮機能変容薬！食後厳守・妊婦禁忌", desc: "小腸上皮のClC-2を開口し水分分泌。空腹時だと高頻度で悪心が出るため【必ず食後（食直後）】に服用。妊婦・妊娠の可能性がある女性は流早産リスクのため禁忌。", gId: "c26", cSec: "sec-extra" },
  { name: "スインプロイク", gen: "ナルデメジントシル酸塩", cat: "26. 慢性便秘症（末梢性μ拮抗薬）", char: "オピオイド誘発性便秘症（OIC）のピンポイント特効薬！鎮痛作用を邪魔しない", desc: "BBBを通過せず末梢の腸管μオピオイド受容体のみを阻害。麻薬性鎮痛薬による便秘を特異的に解除。オピオイド開始・増量時に先手を打って処方される。", gId: "c26", cSec: "sec-extra" },
  { name: "新レシカルボン坐剤", gen: "炭酸水素ナトリウム / 無水リン酸二水素ナトリウム", cat: "26. 慢性便秘症（直腸刺激坐剤）", char: "直腸内で炭酸ガスを発生させて排便反射を直接呼び起こす！直腸性便秘の切り札", desc: "直腸内で炭酸ガス（CO2）を発生し、直腸壁を伸展刺激して排便反射を誘発。出口で詰まる便排出障害や習慣性便秘、術後排便に有効。挿入後15〜30分で排便。", gId: "c26", cSec: "sec-extra" },
  // 101〜120位 専門・がん・難病薬剤
  { name: "タモキシフェン", gen: "タモキシフェン", cat: "101. 乳がん", char: "閉経前乳がんの主軸！SERM製剤で血栓塞栓症（VTE）や子宮内膜変化に注意", desc: "乳腺組織でエストロゲン受容体をブロック。CYP2D6阻害薬（パロキセチン等）併用で活性代謝物エンドキシフェン生成が抑制され効果減弱。深部静脈血栓注意。", gId: "c1", cSec: "sec-onc" },
  { name: "アナストロゾール", gen: "アナストロゾール", cat: "101. 乳がん", char: "閉経後乳がんの第一選択！末梢アロマターゼ阻害で骨粗鬆症・関節痛に注意", desc: "閉経後のエストロゲン産生を元から絶つ。体内のエストロゲン激減により骨塩量低下・骨折リスクが高まるため定期採血・骨密度測定必須。関節のこわばり指導。", gId: "c1", cSec: "sec-onc" },
  { name: "ベージニオ", gen: "アベマシクリブ", cat: "101. 乳がん", char: "進行乳がんの救世主CDK4/6阻害薬！初期の激しい下痢にロペラミド早期対処", desc: "細胞周期G1/S期停止。服用開始数日から2週間に高率で下痢発現。ロペラミド処方準備。好中球減少・間質性肺炎の初期症状（空咳・息切れ）に警戒指導。", gId: "c1", cSec: "sec-onc" },
  { name: "イクスタンジ", gen: "エンザルタミド", cat: "102. 前立腺がん", char: "新規アンドロゲン受容体シグナル阻害薬（ARSI）！てんかん禁忌＆転倒骨折注意", desc: "アンドロゲンの受容体結合・核移行・DNA結合をトリプル遮断。中枢GABA受容体阻害による痙攣リスクからてんかん既往は禁忌。ふらつき・骨折に注意。", gId: "c9", cSec: "sec-onc" },
  { name: "TS-1", gen: "テガフール・ギメラシル・オテラシルK", cat: "103. 経口抗がん剤", char: "胃・大腸・肺がんの外来主軸！指示された休薬期間の遵守が絶対の生命線", desc: "経口フッ化ピリミジン配合剤。休薬忘れによる連日内服は致死的な重篤骨髄抑制を引き起こす。下痢・口内炎・発熱時の即座受診と休薬遵守を徹底指導。", gId: "c1", cSec: "sec-onc" },
  { name: "プログラフ / グラセプター", gen: "タクロリムス", cat: "106. 臓器移植後", char: "拒絶反応を制する免疫抑制の絶対エース！TDM必須＆採血前服用厳禁", desc: "カルシニューリンを阻害しIL-2産生抑制。血中トラフ濃度モニタリング必須。採血当日は採血終了まで飲まない。グレープフルーツ・セイヨウオトギリソウ厳禁。", gId: "c9", cSec: "sec-imm" },
  { name: "プラケニル", gen: "ヒドロキシクロロキン", cat: "108. 全身性エリテマトーデス", char: "SLEの再燃を防ぎ生命予後を延ばす世界標準薬！年1回の定期眼科検査必須", desc: "TLRシグナル阻害等で免疫活性化を抑制。網膜症による不可逆な視力障害を防ぐため、投与前および年1回の眼科精密検査（黄斑部検査）が受診必須条件。", gId: "c16", cSec: "sec-imm" },
  { name: "エブトール", gen: "エタンブトール", cat: "109. 非結核性抗酸菌症", char: "肺MAC症3剤併用の要！球後視神経炎・視力低下・赤緑色覚異常に厳重警戒", desc: "クラリス＋リファンピシンと併用。特有の副作用「球後視神経炎（目のかすみ・視力低下・赤と緑の区別がつかない）」が出たら即服用中止し眼科受診を徹底指導。", gId: "c8", cSec: "sec-inf" },
  { name: "ウテメリン", gen: "リトドリン塩酸塩", cat: "110. 切迫早産", char: "子宮平滑筋弛緩による切迫早産薬！動悸・手指振戦・急激中止のリバウンド注意", desc: "β2受容体刺激で子宮収縮を強力抑制。母体の動悸・頻脈・手の震えが出やすい。自己判断で急にやめると陣痛が急発進するリバウンドがあるため指示通り内服。", gId: "c13", cSec: "sec-extra" },
  { name: "レグテクト", gen: "アカンプロサート", cat: "119. アルコール依存症", char: "お酒を飲みたい渇望を脳から鎮める断酒維持薬！断酒意志のある患者に処方", desc: "グルタミン酸神経伝達を抑制し飲酒欲求を低減。悪酔いさせる薬ではないため断酒意志が前提。腎排泄型のためCcr<50の中等度以上腎機能障害には禁忌・慎重投与。", gId: "c22", cSec: "sec-psy" },
  { name: "セリンクロ", gen: "ナルメフェン", cat: "119. アルコール依存症", char: "飲酒の1〜2時間前に飲む減酒頓服薬！オピオイド鎮痛薬服用者は禁忌", desc: "オピオイド受容体を調節し飲酒による快楽シグナルを遮断して深酒を防ぐ。「飲酒しそうな日の1〜2時間前」に頓服。オピオイド服用者は離脱発現のため禁忌。", gId: "c22", cSec: "sec-psy" },
  { name: "アルマール", gen: "アロチノロール", cat: "120. 本態性振戦", char: "動作時・姿勢時の手の震えを止める第一選択薬！気管支喘息には絶対禁忌", desc: "パーキンソンの安静時振戦と異なり「物を掴む・字を書く」時の震えに著効。末梢β2遮断で震戦を抑制。気管支喘息禁忌・高度徐脈注意。高齢者のふらつき確認。", gId: "c26", cSec: "sec-cv" },

  // 121〜140位 神経難病・感染症・救急薬剤
  { name: "エピペン注射液", gen: "アドレナリン", cat: "139. アナフィラキシー", char: "命を救う唯一無二の救命第一選択！太もも外側に押し当て5秒保持", desc: "α・β全受容体を強力作動し血圧低下と喉頭浮腫を即座に解除。大腿前外側部に直角に強く押し当て5秒保持。使用後は二相性反応の監視のため即座に救急車要請。有効期限管理。", gId: "c16", cSec: "sec-imm" },
  { name: "ネフィ (neffy)", gen: "エピネフリン（アドレナリン）経鼻粉霧液", cat: "139. アナフィラキシー / 新薬", char: "世界初の針なし経鼻アナフィラキシー自己投与薬！太もも注射の恐怖を完全克服", desc: "鼻腔内にワンプッシュ噴霧するだけで鼻粘膜から急速吸収されエピペン筋注と同等血中濃度を達成。30kg以上2mg、15〜30kg1mg。未改善時は5分後反対側へ。使用後直ちに救急要請。", gId: "c16", cSec: "sec-imm" },
  { name: "サインバルタ", gen: "デュロキセチン", cat: "122. 線維筋痛症・慢性疼痛", char: "下行性疼痛抑制系を脳から賦活！NSAIDs無効の慢性腰痛・線維筋痛症に特効", desc: "SNRI作用で下行性疼痛抑制経路を強化。初期の悪心・胃不快感・眠気に注意。急な自己中断による離脱症状（めまい・シャンシャン感）を警告指導。", gId: "c6", cSec: "sec-extra" },
  { name: "芍薬甘草湯", gen: "漢方エキス（ツムラ68番等）", cat: "127. こむら返り", char: "数分で足のつりを解除する神速即効性！甘草過量による偽アルドステロン注意", desc: "芍薬と甘草が筋小胞体Ca再取り込みを促し急速筋弛緩。足がつった時の頓用。甘草高用量（6.0g/日）のため連用による低K血症・浮腫・血圧上昇に厳戒。", gId: "c6", cSec: "sec-extra" },
  { name: "ストロメクトール", gen: "イベルメクチン", cat: "129. 疥癬（かいせん）", char: "ノーベル賞の経口疥癬駆除薬！水のみで空腹時に単回経口服用", desc: "ヒゼンダニの神経Clチャネル遮断。必ず「水のみ空腹時」に単回服用（食後服用は血中濃度過昇）。卵には無効なため1〜2週後にダニ生存確認し再投与。家族一斉治療。", gId: "c16", cSec: "sec-inf" },
  { name: "ステルイズ", gen: "ベンジルペニシリンベンザチン", cat: "132. 梅毒", char: "早期梅毒を単回筋注で治療完結！ヤーリッシュ・ヘルクスハイマー反応注意", desc: "サワシリン4週服用の脱落を防ぐ画期的筋注製剤。臀部深部に単回投与。注射後数時間で出る発熱・皮疹悪化（ヘルクスハイマー反応）を事前告知。パートナー同時検査。", gId: "c8", cSec: "sec-inf" },
  { name: "ビクタルビ", gen: "ビクテグラビル/TAF/FTC", cat: "133. HIV感染症", char: "1日1回1錠のファーストラインART合剤！アドヒアランス95%以上死守指導", desc: "高い抗ウイルス効果と耐性バリア。飲み忘れによる耐性変異獲得を防ぐため95%以上の厳格遵守を指導。Mg/Al制酸剤や鉄剤との2時間以上間隔空け。", gId: "c8", cSec: "sec-inf" },
  { name: "ベムリディ", gen: "テノホビル アラフェナミド（TAF）", cat: "134. B型肝炎", char: "骨・腎毒性を大幅軽減した新世代TAF！自己中断による劇症急性増悪リバウンド警戒", desc: "肝細胞特異的移行で低用量化（TDFの1/10）。自己判断での中止はB型肝炎ウイルスの急激なリバウンド増殖による重症肝炎を起こすため継続内服を徹底。", gId: "c15", cSec: "sec-inf" },
  { name: "マヴィレット", gen: "グレカプレビル/ピブレンタスビル", cat: "134. C型肝炎", char: "8〜12週間内服で95%以上の完全ウイルス排除（SVR）を達成する根治経口薬", desc: "全ジェノタイプ対応DAA製剤。1日1回3錠を食後服用。アトルバスタチンやエチニルエストラジオールピル等との併用禁忌を厳格スクリーニング。", gId: "c15", cSec: "sec-inf" },
  { name: "デカドロンエリキシル", gen: "デキサメタゾン", cat: "138. クループ症候群", char: "ケンケンと響く犬吠様咳嗽・吸気性呼吸困難を鎮火！単回投与で声門下消炎", desc: "クループ症候群に0.15〜0.6mg/kg単回経口投与。長時間作用型ステロイドの強力消炎作用で声門下浮腫を速やかに改善し夜間の窒息リスクを回避。", gId: "c18", cSec: "sec-inf" },
  { name: "フロリードゲル経口用", gen: "ミコナゾール", cat: "125. 口腔カンジダ症", char: "口内に長く含んでから嚥下！ワルファリン併用で出血死リスク絶対禁忌", desc: "吸入ステロイドうがい不足等による口腔カンジダに。口内全体に行き渡らせてから嚥下。ワルファリン併用でCYP2C9を強烈阻害し重篤出血死の危険があり禁忌！", gId: "c16", cSec: "sec-inf" },

  // 141〜150位 自律神経・多汗症・トラベル・フレイル薬剤
  { name: "メドドリン", gen: "ミドドリン塩酸塩", cat: "141. 起立性調節障害", char: "末梢α1作動で立ちくらみ・朝の起き上がれなさを解消！就寝直前服用回避", desc: "選択的α1刺激により末梢血管を収縮させ起立時血圧低下を防止。朝起きられない思春期ODに特効。仰臥位高血圧を防ぐため就寝直前の内服は避けるよう指導。", gId: "c2", cSec: "sec-cv" },
  { name: "グランダキシン", gen: "トフィソパム", cat: "143. 自律神経失調症", char: "視床下部自律神経中枢に選択的作動！抗不安・眠気が極めて少ない調整薬", desc: "交感・副交感のアンバランスを是正。通常のベンゾジアゼピン系と異なり鎮静・筋弛緩作用がほぼ無いため日中眠気が出にくく仕事や学業に支障が出ない。", gId: "c22", cSec: "sec-psy" },
  { name: "エクラープラスター", gen: "デプロドンプロピオン酸エステル", cat: "145. ケロイド・瘢痕", char: "ステロイド密封貼付でケロイドを平坦化！患部の形に正確にハサミで切る", desc: "強力な抗炎症力を持つステロイド貼付テープ。正常皮膚を巻き込まないよう「患部の形にハサミで切って貼る」指導。皮膚菲薄化や毛細血管拡張に注意。", gId: "c16", cSec: "sec-imm" },
  { name: "エクロックゲル", gen: "ソフピロニウム臭化物", cat: "146. 原発性腋窩多汗症", char: "日本初の脇汗外用抗コリン薬！専用アプリケーターで直接塗布し手洗い徹底", desc: "エクリン汗腺M3受容体をブロックし発汗をストップ。アプリケーター使用で手に薬液を付けない。薬液がついた手で目を触ると散瞳・羞明。閉塞隅角緑内障禁忌。", gId: "c16", cSec: "sec-imm" },
  { name: "アポハイドローション", gen: "オキシブチニン塩酸塩", cat: "146. 原発性手掌多汗症", char: "手のひらの汗を止める手掌専用薬！就寝前塗布＆起床後直ちに手洗い徹底", desc: "手掌多汗症に就寝前5プッシュ塗布。起床後直ちに石鹸流水で手を洗う指導が必須。塗布後に目を触ると散瞳・調節障害（目のかすみ）。閉塞隅角緑内障禁忌。", gId: "c16", cSec: "sec-imm" },
  { name: "柿蒂湯", gen: "漢方エキス（ツムラ138番等）", cat: "148. しゃっくり（吃逆）", char: "カキのヘタが横隔膜の痙攣を鎮める吃逆特効薬！温服で速やかな効果発現", desc: "気の逆流を降ろしてしゃっくりを止める。お湯に溶かして温かいうちにゆっくり飲むと即効性が高まる。胃寒・胃腸虚弱にも安全に使用可能。", gId: "c11", cSec: "sec-extra" },
  { name: "ダイアモックス", gen: "アセタゾラミド", cat: "149. 高山病予防", char: "軽度アシドーシスで呼吸を刺激し血中酸素を底上げ！登山前日から服用", desc: "炭酸脱水素酵素阻害により過換気を促し高地低酸素血症を改善。登山前日または当日朝から服用。多尿・手足末梢のピリピリしびれ・炭酸味覚異常に注意指導。", gId: "c13", cSec: "sec-extra" },
  { name: "エンシュア・H", gen: "経腸栄養剤", cat: "150. フレイル・サルコペニア", char: "1mL=1.5kcalの高濃度栄養缶！浸透圧下痢を防ぐため時間をかけゆっくり飲む", desc: "フレイル・低栄養の栄養サポート。一気飲みすると浸透圧下痢や嘔気を起こすため「1缶を30分〜1時間かけてゆっくり飲む」指導。開缶後要冷蔵・24時間以内。", gId: "c10", cSec: "sec-ckd" },

  // 肺線維症・間質性肺炎 抗線維化薬3強
  { name: "オフェブ", gen: "ニンテダニブ", cat: "呼吸器難病（IPF・PF-ILD）", char: "3受容体キナーゼ阻害で肺線維化を阻止！食直後服用＆下痢ロペラミド管理", desc: "IPF、強皮症肺、進行性線維化間質性肺疾患（PF-ILD）に適応。空腹時服用はAUC低下・副作用増のため「食直後」厳守。高頻度の下痢に早期ロペラミド投与・減量規準。", gId: "c11", cSec: "sec-imm" },
  { name: "ピレスパ", gen: "ピルフェニドン", cat: "呼吸器難病（IPF）", char: "元祖抗線維化薬！光線過敏症の徹底遮光指導＆空腹時服用厳禁（食後遵守）", desc: "TGF-β阻害でコラーゲン合成を抑制。最大の注意点は「光線過敏症（外出時の遮光・日焼け止め徹底）」。空腹時内服はCmax急上昇で悪心・嘔吐発現のため必ず「食後」。", gId: "c11", cSec: "sec-imm" },
  { name: "ジャスケイド", gen: "ネランドミラスト", cat: "呼吸器難病（IPF・PPF）", char: "国内10年ぶり新薬！世界初の選択的PDE4B阻害薬で線維化と炎症の両方を遮断", desc: "IPFおよび進行性肺線維症（PPF）に適応。通常1回18mg 1日2回（下痢・体重減少時は9mg減量）。光不安定性のためPTP直前開封（一包化・粉砕不可）。", gId: "c11", cSec: "sec-imm" },
  { name: "サラジェン", gen: "ピロカルピン塩酸塩", cat: "125. 口腔乾燥症（放射線後 / SjS）", char: "頭頸部がん放射線後口渇の【唯一の適応薬】！著明な多汗に注意・喘息絶対禁忌", desc: "非選択的ムスカリン受容体作動薬。放射線治療後とシェーグレン症候群の両方に適応。唾液腺M3刺激で唾液分泌を強力促進。服用後30〜60分で服を着替えるほどの大汗（多汗）が出るが薬効のサイン。自己中断による虫歯多発を警告。気管支喘息は気道攣縮で絶対禁忌！", gId: "c16", cSec: "sec-imm" },
  { name: "エボザック / サリグレン", gen: "セビメリン塩酸塩水和物", cat: "125. 口腔乾燥症（SjS専用）", char: "M1/M3選択的作動薬！シェーグレン症候群専用（放射線後は適応外査定！）", desc: "キヌクリジン誘導体。ピロカルピンに比べ心臓M2への影響が少ない。適応は「シェーグレン症候群の口腔乾燥症状」のみ！頭頸部放射線後の患者に処方された場合は保険適応外（査定対象）。多汗に注意。気管支喘息絶対禁忌。", gId: "c16", cSec: "sec-imm" },
  { name: "サリベート", gen: "人工唾液エアゾール", cat: "125. 口腔乾燥症（局所スプレー）", char: "天然唾液に近い無機塩類スプレー！ムスカリン薬が使えない喘息患者の救世主", desc: "口腔内乾燥時に舌下・頬粘膜に直接1〜2回噴霧。全身性のコリン副作用（多汗・頻尿・腹痛）が一切なく、気管支喘息等でサラジェン・エボザックが禁忌の患者にも極めて安全。", gId: "c16", cSec: "sec-imm" },
  { name: "プリモボラン", gen: "メテノロン酢酸エステル", cat: "128. 血液疾患 / 蛋白同化ステロイド", char: "再生不良性貧血の造血促進 ＆ 慢性消耗性疾患の蛋白同化！女性の不可逆的嗄声注意", desc: "蛋白同化ステロイド。男性化作用を弱め蛋白同化作用を特異的に強化。腎EPO産生促進と骨髄幹細胞直接刺激で赤血球・血小板を産生。女性で一度低くなった声（嗄声）は中止後も戻らない不可逆的変化！前立腺がん絶対禁忌。定期肝機能検査必須。", gId: "c16", cSec: "sec-imm" },
  { name: "ヴォトリエント", gen: "パゾパニブ塩酸塩", cat: "135. 抗がん薬 / 分子標的薬（STS・RCC）", char: "悪性軟部腫瘍・腎細胞癌のマルチTKI！必ず【空腹時服用】＆PPI併用厳禁", desc: "VEGFR/PDGFR/c-Kit阻害薬。食後服用で血中濃度が約2倍に急増し致死的毒性（高血圧・QT延長・穿孔）の危険があるため「食前1時間または食後2時間」の空腹時服用厳守！胃酸で溶解するためPPI併用で吸収が約40%激減（効果消失・原則併用回避）。c-Kit阻害による毛髪の白毛化（白髪化）を事前告知指導。", gId: "c16", cSec: "sec-imm" },
  { name: "アダプチノール", gen: "ヘレニエン", cat: "136. 眼科疾患 / 網膜色素変性症", char: "網膜色素変性症の暗順応改善薬！視物質ロドプシン再合成を促進・遮光厳守", desc: "マリーゴールド由来キサントフィル誘導体（ジパルミチン酸ルテイン）。網膜桿体細胞の視物質ロドプシン再生を促進し暗順応時間を短縮。夜盲症（鳥目）の暗所視力を改善。光に極めて不安定なため粉砕・一包化時は【遮光分包・遮光袋調剤】が絶対必須！", gId: "c16", cSec: "sec-imm" },
  { name: "イフェクサーSR", gen: "ベンラファキシン塩酸塩", cat: "137. 精神神経 / SNRI", char: "用量依存的デュアル作用！SSRI無効の意欲低下・重症うつ病に高用量賦活", desc: "低用量（〜75mg）はSSRI様、高用量（150〜225mg）で強力なノルアドレナリン再取り込み阻害を発揮。徐放性カプセルのため【噛み砕き・粉砕脱カプセル厳禁】。半減期が短く急な自己中断による【激しい離脱症状（めまい・シャンシャン感）】に厳重警戒。高用量時の血圧上昇モニタリング必須。※疼痛適応なし（うつ病のみ）。", gId: "c6", cSec: "sec-psy" },
  { name: "アグリリン", gen: "アナグレリド塩酸塩水和物", cat: "138. 血液疾患 / 本態性血小板血症", char: "巨核球成熟を選択的阻害！非細胞毒性で若年の血小板血症第一選択＆心毒性注意", desc: "本態性血小板血症（ET）治療薬。巨核球の分化・成熟を選択的に抑制し血小板のみを減少（赤血球・白血球に影響なし）。DNA障害性がないため若年患者やハイドレア不耐（下腿潰瘍等）に最適。PDE3阻害作用を併有するため【動悸・頻脈・心不全・QT延長】に厳重警戒（重篤心不全禁忌）。妊婦禁忌・催奇形性あり。", gId: "c16", cSec: "sec-imm" },
  { name: "コランチル", gen: "ジサイクロミン/乾燥水酸化Alゲル/水酸化Mg", cat: "139. 消化器 / 制酸・鎮痙配合剤", char: "即時胃酸中和 ＆ 胃痙攣直接鎮痛！緑内障・前立腺肥大・キレート相互作用に厳戒", desc: "抗コリン薬ジサイクロミン（鎮痙）＋水酸化Al/水酸化Mg（制酸・排便バランス相殺）の古典的配合顆粒。胃炎・胃潰瘍の急な胃痛・さしこみ痛を即座に中和鎮痛。抗コリン作用により【閉塞隅角緑内障・前立腺肥大排尿障害は絶対禁忌】！Al・Mgを含むため【透析患者禁忌】およびニューキノロン・テトラサイクリン・チラージンSとの【金属キレート吸収阻害（2時間以上間隔空け）】が必須。", gId: "c11", cSec: "sec-gi" },
  { name: "グリチロン", gen: "グリチルリチン酸/グリシン/DL-メチオニン", cat: "140. 肝臓・皮膚科 / 抗炎症・解毒配合剤", char: "甘草成分で肝機能改善＆円形脱毛症！漢方薬併用の【偽アルドステロン症・低K】厳戒", desc: "グリチルリチン酸（抗炎症・肝保護）に副作用軽減のグリシン・メチオニンを配合。慢性肝疾患のALT/AST改善、皮膚炎・円形脱毛症（セファランチン併用）に適応。11β-HSD2阻害によりコルチゾールが蓄積し【偽アルドステロン症（低K血症・脱力感・血圧上昇・浮腫）】を惹起。甘草含有漢方薬（芍薬甘草湯等）や利尿薬との併用に厳重警戒。アルドステロン症・低K血症・ミオパチー禁忌。", gId: "c15", cSec: "sec-gi" },
  { name: "フィコンパ", gen: "ペランパネル水和物", cat: "141. 精神神経 / 新規抗てんかん薬（AMPA阻害）", char: "世界初のAMPA受容体拮抗薬！難治性てんかんの切り札＆1日1回就寝前（攻撃性に注意）", desc: "選択的AMPA型グルタミン酸受容体拮抗薬。グルタミン酸による神経過剰興奮をシナプス後膜で直接遮断。部分発作（単剤・併用）および全般強直間代発作（併用）に適応。半減期約105時間の超持続型で1日1回就寝前服用。めまい・眠気・ふらつきのほか【易怒性・攻撃性・敵意等の精神症状】に厳重警戒（家族からの聞き取り重要）。カルバマゼピン併用で濃度半減（CYP3A誘導）。", gId: "c6", cSec: "sec-psy" },
  { name: "ヘキザック", gen: "クロルヘキシジングルコン酸塩", cat: "142. 外用消毒薬 / ビグアナイド系殺菌消毒薬", char: "皮膚ケラチン吸着で持続殺菌No.1！【濃度別厳守（0.02%〜1%）】＆内耳・脳神経絶対禁忌", desc: "ビグアナイド系外用殺菌消毒薬。細菌細胞膜破壊により広範な殺菌効果と優れた皮膚残留持続性を発揮。濃度別使い分けが超重要：①粘膜・創傷部・口腔内は【0.02%（250倍希釈）】、②手指・正常皮膚は【0.1〜0.5%】、③手術野・CVC穿刺部は【0.5〜1%エタノール液】。🚨【絶対禁忌】：不可逆的難聴・神経麻痺を起こすため「内耳・中耳・脳・脊髄神経・眼」への侵入は絶対厳禁！石けん（アニオン）併用で沈殿失活。アナフィラキシーショック注意。", gId: "c16", cSec: "sec-imm" },
  { name: "ネオステリングリーン", gen: "ベンゼトニウム塩化物", cat: "143. 歯科・口腔用薬 / 含嗽用殺菌消毒薬（第4級アンモニウム塩）", char: "歯科・抜歯後の第一選択！【抜歯当日強いうがい厳禁（ドライソケット予防）】＆歯磨き粉失活注意", desc: "第4級アンモニウム塩系（カチオン界面活性剤）の含嗽用殺菌消毒薬。抜歯創・口腔手術創の感染予防、口内炎、咽頭炎に適応。1回数滴（約0.5mL）を水約50mL（約100倍、0.002%）に希釈して含嗽。🚨【重要指導】：①抜歯当日に強くブクブクうがいをすると血餅が剥離し激痛を伴う「ドライソケット」を引き起こすため当日はそっと吐き出す程度にする、②歯磨き粉のラウリル硫酸Na（アニオン）で沈殿失活するため歯磨き直後は水洗徹底、③原液使用・嚥下（飲み込み）厳禁。ヨード過敏や甲状腺疾患患者にも安心。", gId: "c16", cSec: "sec-imm" },
  { name: "ベリチーム", gen: "パンクレアチン/ビオヂアスターゼ1000/セルラーゼAP3/パンクレリパーゼ", cat: "144. 消化器官用薬 / 複合消化酵素製剤（4大栄養素全対応）", char: "糖質・蛋白・脂肪・繊維素すべて分解！【豚肉アレルギー絶対禁忌】＆熱湯失活＆食直後服用", desc: "起源と至適pHが異なる4種の酵素（豚膵臓由来パンクレアチン・パンクレリパーゼ、糸状菌由来ビオヂアスターゼ・セルラーゼ）を配合した複合消化酵素剤。胃内〜腸管までの広範なpHで消化促進。慢性膵炎、胃切除後、胆道疾患等の消化異常・脂肪便・食欲不振を改善。🚨【調剤鑑査・指導】：①豚由来酵素のため「豚肉アレルギー」患者には絶対禁忌、②酵素が熱変性するため「熱いお茶や熱湯」での服用厳禁（ぬるま湯・水）、③食べ物と混ざることで効くため「食直後または食事中」服用厳守、④口内に残すと粘膜蛋白分解で口内炎・潰瘍のリスク。", gId: "c11", cSec: "sec-gi" },
  { name: "ポリフル", gen: "ポリカルボフィルカルシウム", cat: "145. 消化器官用薬 / 高分子過敏性腸症候群（IBS）水分保持・便性状改善薬", char: "下痢にも便秘にも両方効く！【必ずコップ1杯（200mL）以上の水で服用】＆胃酸必須＆キレート", desc: "高分子吸水性ポリマー製剤。胃内（強酸性）でカルシウムが脱離し、腸管内（弱酸性〜中性）で自重の数十倍の水分を保持してゲル化。下痢では水分を吸着して固め、便秘では便容積と水分を保って軟化させる両向性便通改善薬。下痢型・便秘型・混合型すべてのIBSに適応。🚨【調剤鑑査・指導】：①水が少ないと食道閉塞や糞便塞栓・腸閉塞を招くため「必ずコップ1杯（200mL以上）の水」で服用、②胃酸でCaが解離しないと効果激減（PPI・タケキャブ併用や無酸症で減弱）、③外れたCaがニューキノロン・テトラサイクリンとキレート形成（2時間以上間隔）、高Ca血症・イレウス禁忌。", gId: "c11", cSec: "sec-gi" },
  { name: "グラアルファ", gen: "リパスジル塩酸塩水和物/ブリモニジン酒石酸塩", cat: "146. 眼科用薬 / ROCK阻害・α2作動薬配合緑内障点眼薬", char: "PG製剤上乗せの切り札！【点眼直後の白目充血（1〜2時間で消失・事前予告必須）】＆1日2回＆目頭押さえ", desc: "ROCK阻害薬（リパスジル）と選択的α2受容体作動薬（ブリモニジン）の配合点眼液。主流出路流出促進＋副流出路流出促進＋房水産生抑制のトリプル作用。β遮断薬フリー（喘息・心不全も安心）かつPGフリー（DUES・まぶたくぼみなし）で、キサラタン等のPG製剤への上乗せ第一選択。1日2回点眼。🚨【重要指導】：①血管拡張により点眼数分後から白目が真っ赤に充血するが1〜2時間で自然消失するため「効いている証拠」と事前予告必須、②長期連用時のアレルギー性眼瞼結膜炎に注意、③点眼後目頭を軽く押さえ全身移行（眠気・徐脈・低血圧）防止。", gId: "c14", cSec: "sec-eye" },
  { name: "ロゼックス", gen: "メトロニダゾール", cat: "147. 皮膚科・緩和ケア / 抗原虫・抗菌・抗炎症外用薬", char: "酒さ（赤ら顔）の第一選択＆がん性皮膚潰瘍の悪臭を劇的消去！【ステロイド酒さ悪化回避】＆遮光", desc: "ニトロイミダゾール系外用ゲル（0.75%）。①酒さ（赤ら顔・丘疹・膿疱）：好中球活性酸素産生抑制とニキビダニ抑制で抗炎症。ステロイドのような皮膚萎縮を起こさず長期維持可能。1日2回洗顔後塗布。②がん性皮膚潰瘍の悪臭軽減：自壊創に繁殖した偏性嫌気性菌を殺菌し耐えがたい腐敗臭を数日で劇的消失（緩和ケア必須）。🚨【調剤鑑査・指導】：酒さにステロイド連用は酒さ様皮膚炎で悪化するため禁忌、紫外線（日光）で分解・病勢悪化するため日焼け止め・遮光徹底、創傷部にはガーゼ貼付、大量塗布時アルコール注意。", gId: "c16", cSec: "sec-imm" },
  { name: "ル・エストロジェル", gen: "エストラジオール", cat: "148. 婦人科・内分泌 / 経皮吸収型卵胞ホルモン製剤", char: "テープかぶれの救済＆低血栓リスク！【胸（乳房）塗布絶対厳禁】＆子宮体がん予防黄体ホルモン併用＆接触防止", desc: "ポンプ式経皮エストロゲンゲル製剤（0.06%）。肝初回通過効果を完全回避し静脈血栓塞栓症（VTE）リスクが経口剤に比べ極めて低値。エストラーナテープでかぶれる患者の救済第一選択。1日1回通常2プッシュを手腕部または太ももに広く薄く塗布。🚨【調剤鑑査・指導】：①乳房痛・乳がんリスク回避のため「胸部（乳房・デコルテ）」塗布は絶対厳禁！②子宮のある女性は子宮体がん（子宮内膜増殖症）防止のため「黄体ホルモン製剤（エフメノ等）」の併用が必須（未併用は疑義照会）、③小児・男性への思春期早発二次曝露防止のため塗布直後手洗い・衣服被覆徹底、④ゴシゴシ擦り込まず2〜5分乾燥。", gId: "c13", cSec: "sec-obgyn" },
  { name: "ノイロトロピン", gen: "ワクシニアウイルス接種家兎炎症皮膚抽出液", cat: "149. 整形外科・疼痛管理 / 下行性疼痛抑制系賦活型 鎮痛・自律神経調整薬", char: "痛みのブレーキを活性化＆胃・腎障害なし！【即効性なし（2〜4週間継続必須）】＆眠気極少高齢者安心", desc: "ウサギの炎症皮膚抽出非タンパク性生物活性エキス製剤。脳幹から脊髄へ痛みを遮断する「下行性疼痛抑制系（セロトニン・ノルアドレナリン系）」を賦活し、末梢血流改善・ブラジキニン遊離抑制を発揮。腰痛症、頸肩腕症候群、帯状疱疹後神経痛、アレルギー性鼻炎に適応。🚨【調剤鑑査・指導】：①ロキソニンのような即効性はなく効果発現に2〜4週間要するため「じっくり続ける安心指導」が必須、②NSAIDsのような胃潰瘍・腎不全リスクがなく、リリカやサインバルタのような眠気・ふらつき（転倒リスク）が極めて少なく高齢者に超安全、③通常1回4単位（2錠）を1日2回（朝夕計4錠）服用。", gId: "c10", cSec: "sec-pain" },
  { name: "グラケー", gen: "メナテトレノン", cat: "150. 代謝・骨粗鬆症用薬 / 活性型ビタミンK2（骨質改善・オステオカルシン活性化）製剤", char: "骨密度だけでなく「骨質」を強化！【ワーファリン併用絶対禁忌】＆【食後服用厳守（空腹時吸収1/3）】", desc: "活性型ビタミンK2（メナテトレノン）製剤。骨芽細胞が分泌する未熟なオステオカルシン（ucOC）のグルタミン酸残基をγ-カルボキシル化（Gla化）し、カルシウムを骨基質コラーゲン線維に強力に沈着・結合させて骨強度（骨質）を強化、骨折を予防する。骨粗鬆症における骨塩量・疼痛改善に適応。通常1回15mgを1日3回毎食後経口投与。🚨【調剤鑑査・指導】：①【絶対併用禁忌】：ワーファリン（ワルファリン）の抗凝固作用を完全に阻害し血栓症・塞栓症（脳梗塞等）を惹起（DOACは影響なし）、②【食後服用厳守】：極めて高脂溶性のため胆汁酸分泌のない空腹時服用ではバイオアベイラビリティが約1/3に激減し無効化、③消化器症状（胃部不快感・下痢）に注意。", gId: "c13", cSec: "sec-metab" },
  { name: "ドボベット", gen: "カルシポトリオール水和物/ベタメタゾンジプロピオン酸エステル", cat: "151. 皮膚科用薬 / 尋常性乾癬治療 活性型ビタミンD3・ステロイド配合外用剤", char: "乾癬治療の世界的第一選択！【週90g上限＆高Ca血症警戒】＆【顔面陰部原則禁止】＆【フォーム振盪必須】", desc: "活性型ビタミンD3（表皮角化細胞増殖抑制・正常分化誘導）とベリーストロングⅡ群ステロイド（強力消炎・IL-17/23産生抑制）の配合外用剤。単剤併用よりも効果発現が速く、ステロイドがVD3の皮膚刺激感を抑え、VD3が皮膚萎縮を相殺する理想のシナジー。軟膏（局面・浸透）、ゲル（頭部有毛部・ベタつき防止）、フォーム（広範囲・泡状）の3剤形。1日1回患部に塗布。🚨【調剤鑑査・指導】：①【週90g上限＆高Ca血症警戒】：VD3の経皮吸収による高カルシウム血症（口渇、倦怠感、食欲不振、急性腎不全）防止のため全剤形合算で「1週間に90g」が厳格な上限、②【顔面・外陰部・粘膜は絶対回避】：高吸収による皮膚萎縮・潮紅回避、③【フォーム剤は直前に上下によく振る（振盪必須）】＆下向き噴射、④塗布後は直ちに石けんで手洗い。", gId: "c16", cSec: "sec-derm" },
  { name: "コレバイン", gen: "コレスチミド", cat: "152. 代謝・脂質異常症用薬 / 陰イオン交換樹脂・胆汁酸吸着薬（非吸収性LDL降下薬）", char: "腸から吸収されない超安全設計！【他剤との服用間隔1時間以上厳守（強力吸着）】＆便秘・多めの水", desc: "高分子陰イオン交換樹脂製剤。消化管内で胆汁酸と強固に結合し糞便中へ排泄（腸肝循環遮断）。肝コレステロールからの胆汁酸合成促進とLDL受容体発現増加により血中LDL-Cを低下させる。体内に一切吸収されないため肝・腎障害患者や妊婦、スタチン横紋筋融解症リスク患者にも安全。🚨【調剤鑑査・指導】：①【他剤併用吸着注意】：酸性薬物（ワーファリン、甲状腺ホルモン、ジゴキシン、利尿薬等）や脂溶性ビタミンを強力に吸着し吸収を著しく阻害するため「他剤の服用前後1時間以上あけて服用」必須、②水分を吸って膨潤するため便秘・硬便が好発、「多めの水（コップ1杯以上）」で服用、重篤な便秘・腸閉塞患者禁忌、③代償性に中性脂肪（TG）が上昇することがある。", gId: "c1", cSec: "sec-lipid" },

];

// --- 2. タブ切り替えロジック ＆ ヘッダーナビゲーション ---
function switchTab(tabId, scrollToTop = false) {
  const panes = document.querySelectorAll('.tab-pane');
  panes.forEach(p => p.classList.remove('active'));

  const navBtns = document.querySelectorAll('.tab-nav .tab-btn, .main-nav-btn');
  navBtns.forEach(b => {
    b.classList.remove('active');
    const oc = (b.getAttribute && b.getAttribute('onclick')) || '';
    const dt = (b.getAttribute && b.getAttribute('data-tab')) || '';
    if (oc.includes(tabId) || dt === tabId) {
      b.classList.add('active');
    }
  });

  const targetPane = document.getElementById(tabId);
  if (targetPane) {
    targetPane.classList.add('active');
  }

  if (tabId === 'tab-favorites' && typeof renderFavoritesHub === 'function') {
    renderFavoritesHub();
  }

  if (scrollToTop) {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
}

function triggerQuickPrint() {
  window.print();
}

// ==========================================================================
// スムーズスクロール＆パルスハイライト共通関数（固定ヘッダー自動オフセット対応）
// ==========================================================================
function smoothScrollToElement(elem, customOffset) {
  if (!elem) return;
  const navbar = document.querySelector('.navbar');
  const navHeight = navbar ? navbar.offsetHeight : 110;
  const offset = (typeof customOffset === 'number') ? customOffset : (navHeight + 20);

  setTimeout(() => {
    const rect = elem.getBoundingClientRect();
    const scrollTop = window.pageYOffset || (document.documentElement ? document.documentElement.scrollTop : 0) || 0;
    const targetY = rect.top + scrollTop - offset;

    window.scrollTo({
      top: Math.max(0, targetY),
      behavior: 'smooth'
    });

    elem.classList.remove('target-pulse');
    void elem.offsetWidth; // リフロー強制
    elem.classList.add('target-pulse');
  }, 100);
}

function clearSearch() {
  const heroInput = document.getElementById('drug-search-input');
  if (heroInput) heroInput.value = '';
  const sDrop = document.getElementById('suggest-dropdown');
  if (sDrop) sDrop.style.display = 'none';
  const sBox = document.getElementById('suggestBox');
  if (sBox) sBox.style.display = 'none';
}

function handleHeroSearchKeydown(e, input) {
  if (e.key === 'Escape') {
    const d = document.getElementById('suggest-dropdown');
    if (d) d.style.display = 'none';
  } else if (e.key === 'Enter') {
    e.preventDefault();
    quickSearch(input.value.trim());
  }
}

function quickSearch(keyword) {
  executeUniversalSearch(keyword);
}



