// 調剤適合性情報の検索関数（名称・一般名で柔軟にマッチング）
function getCompoundingInfo(drugName, genName) {
  if (!drugName && !genName) return null;
  const dName = (drugName || '').toLowerCase();
  const gName = (genName || '').toLowerCase();

  for (const [key, val] of Object.entries(COMPOUNDING_MASTER)) {
    const k = key.toLowerCase();
    if (dName.includes(k) || gName.includes(k) || k.includes(dName)) {
      return { key, ...val };
    }
  }

  // デフォルト未登録時
  return {
    key: drugName || genName || '',
    crush: "unknown",
    susp: "unknown",
    pack: "unknown",
    crushText: "➖ 要確認",
    suspText: "➖ 要確認",
    packText: "➖ 要確認",
    reason: "調剤適合性データ未登録です。最新の添付文書・インタビューフォーム・簡易懸濁法ハンドブックをご確認ください。",
    alt: "ー"
  };
}

// 臨床事典タブの各薬品カードへのバッジ自動挿入
function initDictCompoundingBadges() {
  const cards = document.querySelectorAll('#dictCardsContainer .dict-card[data-type="drug"]');
  cards.forEach(card => {
    if (card.querySelector('.compounding-badges')) return; // 二重生成防止

    const drugName = card.getAttribute('data-name') || '';
    const subElem = card.querySelector('.dict-card-sub');
    const genName = subElem ? subElem.innerText : '';
    const info = getCompoundingInfo(drugName, genName);
    if (!info) return;

    const badgesDiv = document.createElement('div');
    badgesDiv.className = 'compounding-badges';
    badgesDiv.innerHTML = `
      <span class="c-badge ${info.crush}" title="粉砕可否 (クリックで詳細表へ)" onclick="event.stopPropagation(); jumpToCrush('${info.key}')">💊 粉砕: ${info.crushText}</span>
      <span class="c-badge ${info.susp}" title="簡易懸濁可否 (55℃温湯通過性)" onclick="event.stopPropagation(); jumpToCrush('${info.key}')">💧 懸濁: ${info.suspText}</span>
      <span class="c-badge ${info.pack}" title="一包化適否 (吸湿・遮光)" onclick="event.stopPropagation(); jumpToCrush('${info.key}')">📦 一包化: ${info.packText}</span>
    `;

    if (subElem && subElem.parentNode) {
      subElem.parentNode.insertBefore(badgesDiv, subElem.nextSibling);
    }
  });
}

// ==========================================================================
// 臨床薬学実務 統合表記ゆれ辞書 ＆ 正規化エンジン
