// ==========================================================================
// 主要20大疾患 病型別第一選択薬マスター 検索＆ダイレクトジャンプ機能
// ==========================================================================
function filterFirstlineTable() {
  const input = document.getElementById('firstlineFilterInput');
  if (!input) return;
  const terms = input.value.trim().toLowerCase().split(/\s+/).filter(Boolean);
  const rows = document.querySelectorAll('#firstlineTable tbody tr.firstline-row');
  
  rows.forEach(row => {
    if (terms.length === 0) {
      row.style.display = '';
      return;
    }
    const text = row.innerText.toLowerCase();
    const match = terms.every(term => text.includes(term));
    row.style.display = match ? '' : 'none';
  });
}

function jumpToFirstLine(keyword) {
  closeDrugModal();
  switchTab('tab-profiling');
  switchProfilingView('all', null);
  const target = document.getElementById('firstline-master-section');
  if (target) {
    smoothScrollToElement(target);
    if (keyword) {
      const input = document.getElementById('firstlineFilterInput');
      if (input) {
        input.value = keyword;
        filterFirstlineTable();
      }
    }
  }
}


// ==========================================================================
// 全疾患・全主要薬剤 確認すべきこと ＆ 副作用完全マトリクス 検索＆フィルター
// ==========================================================================
let currentMonitorCat = 'all';

function filterMonitorCategory(catClass, btn) {
  currentMonitorCat = catClass;
  const pills = document.querySelectorAll('.monitor-cat-pill');
  pills.forEach(p => {
    p.classList.remove('active');
    p.style.background = '#f8fafc';
    p.style.color = '#334155';
    p.style.borderColor = '#cbd5e1';
  });
  if (btn) {
    btn.classList.add('active');
    btn.style.background = '#6366f1';
    btn.style.color = 'white';
    btn.style.borderColor = '#6366f1';
  }
  filterMonitorTable();
}

function filterMonitorTable() {
  const input = document.getElementById('monitorFilterInput');
  const terms = input ? input.value.trim().toLowerCase().split(/\s+/).filter(Boolean) : [];
  const rows = document.querySelectorAll('#monitorMasterTable tbody tr.monitor-row');
  
  rows.forEach(row => {
    const matchesCat = (currentMonitorCat === 'all') || row.classList.contains(currentMonitorCat);
    if (!matchesCat) {
      row.style.display = 'none';
      return;
    }
    if (terms.length === 0) {
      row.style.display = '';
      return;
    }
    const text = row.innerText.toLowerCase();
    const matchesText = terms.every(t => text.includes(t));
    row.style.display = matchesText ? '' : 'none';
  });
}

function jumpToDiseaseCheck(cat, scrollToTop = true) {
  closeDrugModal();
  switchTab('tab-followup', false);
  const dCheckBtn = document.querySelector('.followup-nav-tabs .tab-btn[onclick*="f-disease-symptom-check"]');
  showFu('f-disease-symptom-check', dCheckBtn);

  // ナビバーの「🩺 疾患別 症状＆薬剤確認」ボタンをアクティブ表示にする
  const navBtns = document.querySelectorAll('.tab-nav .tab-btn, .main-nav-btn');
  navBtns.forEach(b => {
    b.classList.remove('active');
    const oc = (b.getAttribute && b.getAttribute('onclick')) || '';
    if (oc.includes('jumpToDiseaseCheck')) {
      b.classList.add('active');
    }
  });

  if (cat) {
    const fBtn = document.querySelector(`.disease-filter-btn[onclick*="${cat}"]`);
    filterDiseaseCheck(cat, fBtn);
  }

  const target = document.querySelector('.f-disease-symptom-check');
  if (target) {
    if (scrollToTop) {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
      smoothScrollToElement(target);
    }
  }
}

function jumpToMonitoring(category, keyword) {
  closeDrugModal();
  switchTab('tab-followup');
  showFu('f-monitor-master', null);
  const target = document.querySelector('.f-monitor-master');
  if (target) {
    smoothScrollToElement(target);
    if (category) {
      const btn = document.querySelector(`.monitor-cat-pill[onclick*="${category}"]`);
      filterMonitorCategory(category, btn);
    }
    if (keyword) {
      const input = document.getElementById('monitorFilterInput');
      if (input) {
        input.value = keyword;
        filterMonitorTable();
      }
    }
  }
}

