function detectDosePhase(primaryDrug, customDrugs, rawText) {
  const allTexts = [
    (primaryDrug || ''),
    ...(customDrugs || []),
    (rawText || wizardState.rawPrescriptionText || '')
  ].join(' ');

  const detected = [];
  for (const rule of DOSE_PHASE_RULES) {
    if (rule.drugRegex.test(allTexts)) {
      for (const d of rule.doses) {
        if (d.matchRegex.test(allTexts)) {
          detected.push({
            drugName: rule.drugRegex.source.split('|')[0],
            ...d
          });
          break;
        }
      }
    }
  }
  return detected;
}

